// 历史人物（11—15 世纪）：宋元明之际的中国、蒙古帝国、伊斯兰世界与欧亚非之间的旅行者。
import type { Figure } from '../../types.ts';
import { w } from './waypoint.ts';

export const FIGURES_MEDIEVAL: Figure[] = [
  {
    id: 'su-shi',
    name: { zh: '苏轼', en: 'Su Shi' },
    birth: 1037, death: 1101,
    title: { zh: '文学家、书画家', en: 'Writer, poet and calligrapher' },
    region: 'china', lineage: 'china', sprite: 'walker',
    summary: {
      zh: '北宋文学家、书画家，字子瞻，号东坡居士。诗、词、文、书、画皆冠绝一时，为“唐宋八大家”之一，开创豪放词风。他仕途坎坷，因“乌台诗案”及新旧党争屡遭贬谪，足迹遍及大江南北直至海南，却始终乐观旷达，留下《赤壁赋》《水调歌头》等千古名篇。',
      en: 'Northern Song writer, poet, calligrapher and painter, also known as Su Dongpo. One of the "Eight Masters of the Tang and Song", he excelled in prose and in both shi and ci poetry, and is credited with founding the bold, unrestrained style of ci. Caught between the reformist and conservative factions at court, he was imprisoned in the Crow Terrace Poetry Case and repeatedly exiled, finally as far as Hainan. He met these reverses with humour and equanimity, and works such as the Red Cliff odes and "Prelude to Water Melody" remain among the best loved in Chinese literature.',
    },
    route: [
      w(1037, 103.83, 30.05,
        ['眉山（今四川眉山）', '生于眉州眉山', '苏轼生于眉州眉山的一个读书人家，父亲苏洵、弟弟苏辙后来都以文章名世，父子三人合称“三苏”。少年时他在母亲程氏的教导下读书，立志以古代名臣为榜样。'],
        ['Meishan (now Meishan, Sichuan)', 'Born in Meishan, Meizhou', 'Su Shi was born into a scholarly family in Meishan. His father Su Xun and younger brother Su Zhe also became celebrated writers, and the three are known together as the "Three Sus". He received much of his early education from his mother, Lady Cheng.']),
      w(1057, 114.31, 34.8,
        ['汴京（今河南开封）', '与弟苏辙同榜进士，得欧阳修赏识', '苏轼随父亲出蜀赴京应试，与弟弟苏辙同榜考中进士。主考官欧阳修读到他的文章大为赞赏，说要“放他出一头地”。不久母亲病故，兄弟二人回乡守丧。'],
        ['Bianjing (now Kaifeng, Henan)', 'Passes the jinshi examination with his brother', 'Su Shi travelled from Sichuan to the capital with his father and passed the jinshi examination in the same year as his brother Su Zhe. The chief examiner, Ouyang Xiu, admired his essay and predicted that he would outshine his elders. Their mother died soon afterwards and the brothers went home to mourn.']),
      w(1061, 107.39, 34.52,
        ['凤翔（今陕西凤翔）', '任凤翔府签判', '苏轼通过制科考试，被任命为凤翔府签书判官，这是他的第一个地方官职。任内遇久旱得雨，他把新建的亭子命名为“喜雨亭”，并写下《喜雨亭记》。'],
        ['Fengxiang (now Fengxiang, Shaanxi)', 'First post, as assistant magistrate in Fengxiang', 'After passing a special decree examination, Su Shi was sent to Fengxiang as notary to the prefectural administration, his first provincial post. When rain ended a long drought he named a newly built pavilion the Pavilion of Joyful Rain and wrote an essay to mark the occasion.']),
      w(1071, 120.16, 30.27,
        ['杭州', '因反对新法外放杭州通判', '王安石推行变法，苏轼多次上书批评新法的弊端，随后自请外任，出为杭州通判。在杭三年，他遍游湖山，写下“欲把西湖比西子，淡妆浓抹总相宜”的名句。'],
        ['Hangzhou', 'Sent to Hangzhou after opposing the New Policies', 'Su Shi repeatedly criticised the reforms of Wang Anshi and then asked for a post away from court, becoming vice-prefect of Hangzhou. During three years there he explored the lakes and hills and wrote the well-known poem comparing West Lake to the beauty Xi Shi.']),
      w(1074, 119.4, 36.0,
        ['密州（今山东诸城）', '知密州，作《水调歌头·明月几时有》', '苏轼调任密州知州，当地连年蝗旱，他组织捕蝗、收养弃婴。1076年中秋，他在超然台上饮酒怀念弟弟苏辙，写下《水调歌头·明月几时有》。'],
        ['Mizhou (now Zhucheng, Shandong)', 'Governs Mizhou and writes "Prelude to Water Melody"', 'As prefect of Mizhou, Su Shi dealt with locusts and drought and arranged care for abandoned infants. At the Mid-Autumn Festival of 1076, drinking on the Chaoran Terrace and missing his brother Su Zhe, he wrote the lyric that begins "When will the bright moon appear?"']),
      w(1077, 117.18, 34.26,
        ['徐州', '知徐州，率军民抗洪', '苏轼到任不久，黄河在澶州决口，洪水围困徐州城。他住在城墙上指挥军民筑堤护城，一直坚守到洪水退去。次年他在城东门建“黄楼”作为纪念。'],
        ['Xuzhou', 'Leads flood defences as prefect of Xuzhou', 'Soon after Su Shi took office the Yellow River burst its dykes at Chanzhou and floodwater surrounded Xuzhou. He camped on the city wall, directing soldiers and townspeople as they raised embankments, until the water receded. The next year he built the Yellow Tower by the east gate in commemoration.']),
      w(1079, 120.09, 30.89,
        ['湖州', '“乌台诗案”发，在任上被捕', '苏轼调任湖州知州才三个月，御史们摘取他诗文中的字句，弹劾他讥讽朝政、诽谤新法。朝廷派人赶到湖州，把他从州衙中押走，解往京城受审。'],
        ['Huzhou', 'Arrested in office in the Crow Terrace Poetry Case', 'Su Shi had been prefect of Huzhou for only three months when censors, quoting lines from his poems and memorials, accused him of slandering the court and its reforms. Officers arrived from the capital, seized him at his office and escorted him north for trial.']),
      w(1079, 114.31, 34.8,
        ['汴京（今河南开封）', '系御史台狱四个多月', '苏轼被关押在御史台，因台中柏树上常有乌鸦栖息，御史台别称“乌台”，此案因而得名。他一度以为必死，写诗与弟弟诀别；经多方营救，年底获释，贬往黄州。'],
        ['Bianjing (now Kaifeng, Henan)', 'Held for over four months in the Censorate prison', 'Su Shi was interrogated in the prison of the Censorate, nicknamed the Crow Terrace after the birds that roosted in its cypress trees. Expecting execution, he wrote farewell poems to his brother. After appeals from many quarters he was released at the end of the year and banished to Huangzhou.']),
      w(1080, 114.87, 30.45,
        ['黄州（今湖北黄冈）', '贬黄州团练副使，作前后《赤壁赋》', '苏轼在黄州只有虚衔、不得签署公事，生活困窘，便在城东坡地开荒种田，自号“东坡居士”。1082年他两次泛舟赤壁，写下前后《赤壁赋》；书法名作《寒食帖》也写于这一年。'],
        ['Huangzhou (now Huanggang, Hubei)', 'Exiled to Huangzhou, where he writes the Red Cliff odes', 'In Huangzhou Su Shi held a nominal title with no duties and little income, so he farmed a plot on the eastern slope and took the name Dongpo, "Eastern Slope". In 1082 he twice went boating beneath the Red Cliff and wrote his two odes; his calligraphic masterpiece, the Cold Food Observance, dates from the same year.'],
        { wiki: { zh: '寒食帖', en: 'The Cold Food Observance' } }),
      w(1084, 115.98, 29.56,
        ['庐山（今江西九江）', '离黄州，游庐山作《题西林壁》', '朝廷将苏轼改迁汝州，他离开居住四年多的黄州，顺江东下，途中登游庐山十余日。在西林寺的墙壁上，他题下“不识庐山真面目，只缘身在此山中”。'],
        ['Mount Lu (near Jiujiang, Jiangxi)', 'Leaves Huangzhou and visits Mount Lu', 'Transferred nominally to Ruzhou, Su Shi left Huangzhou after more than four years and travelled down the Yangtze, stopping to spend some ten days on Mount Lu. On a wall of Xilin Temple he wrote the quatrain ending "I cannot tell the true face of Mount Lu, because I am in the mountain myself."'],
        { wiki: { zh: '庐山', en: 'Mount Lu' } }),
      w(1084, 118.78, 32.06,
        ['江宁（今江苏南京）', '在金陵拜会王安石', '苏轼路过江宁，专程拜访已罢相闲居的王安石。两位昔日的政敌同游钟山、唱和诗文，相处月余。王安石事后感叹：“不知更几百年，方有如此人物。”'],
        ['Jiangning (now Nanjing, Jiangsu)', 'Calls on Wang Anshi in retirement', 'Passing through Jiangning, Su Shi visited Wang Anshi, the former chief minister whose reforms he had opposed and who now lived in retirement. The two spent several weeks touring Zhongshan and exchanging poems. Wang is said to have remarked that centuries might pass before another such man appeared.']),
      w(1085, 120.75, 37.81,
        ['登州（今山东蓬莱）', '知登州，到任五日即被召回', '宋神宗去世后旧党执政，苏轼被起用为登州知州。他到任仅五天就接到召他回京的诏令，却已看到了难得一见的海市蜃楼，写下《登州海市》诗，并上书请求变通当地的榷盐之法。'],
        ['Dengzhou (now Penglai, Shandong)', 'Prefect of Dengzhou for five days', 'After Emperor Shenzong died and the conservatives returned to power, Su Shi was appointed prefect of Dengzhou. An order recalling him to the capital arrived only five days after he took office, but he had time to see the famous sea mirage and write a poem on it, and to petition for relief from the local salt monopoly.'],
        { wiki: { zh: '蓬莱阁', en: 'Penglai Pavilion' } }),
      w(1086, 114.31, 34.8,
        ['汴京（今河南开封）', '旧党执政，召回任翰林学士', '苏轼回京后连续升迁，官至翰林学士、知制诰，负责起草诏令。但他不赞成司马光尽废新法，主张保留免役法等可行的措施，因而又受到旧党中人的攻击。'],
        ['Bianjing (now Kaifeng, Henan)', 'Recalled to court as a Hanlin academician', 'Back in the capital Su Shi was promoted rapidly to Hanlin academician, drafting edicts for the throne. He disagreed, however, with Sima Guang\'s wholesale abolition of the New Policies and argued for keeping workable measures such as the hired-service system, which drew attacks from his own side.']),
      w(1089, 120.16, 30.27,
        ['杭州', '出知杭州，疏浚西湖、筑“苏堤”', '苏轼为避开朝中纷争请求外任，以龙图阁学士出知杭州。当时西湖淤塞过半，他招募民夫疏浚，用挖出的淤泥葑草筑成一条贯通南北的长堤，后人称为“苏堤”。'],
        ['Hangzhou', 'Governs Hangzhou and dredges West Lake', 'To escape factional quarrels Su Shi asked to leave court and returned to Hangzhou as prefect. West Lake was by then half choked with weeds and silt. He hired labourers to dredge it and used the spoil to build a causeway across the lake from north to south, known ever since as the Su Causeway.'],
        { wiki: { zh: '西湖', en: 'West Lake' } }),
      w(1093, 114.99, 38.52,
        ['定州（今河北定州）', '高太后去世，出知定州', '支持旧党的太皇太后高氏去世，宋哲宗亲政，新党重新得势。苏轼被外放到北方边境的定州，在那里整顿松弛的军纪、修缮营房。半年多后，贬谪的命令接踵而至。'],
        ['Dingzhou (now Dingzhou, Hebei)', 'Posted to the northern frontier at Dingzhou', 'When Grand Empress Dowager Gao died and Emperor Zhezong began to rule in person, the reformers returned to power. Su Shi was sent out to Dingzhou on the northern frontier, where he tightened lax military discipline and repaired the barracks. Within months orders of demotion followed one after another.']),
      w(1094, 114.41, 23.11,
        ['惠州', '再遭贬谪至惠州', '苏轼以“讥讪先朝”的罪名被贬往岭南，年近六十翻越大庾岭来到惠州。他在此写下“日啖荔枝三百颗，不辞长作岭南人”，还资助修桥；陪伴他南来的侍妾王朝云病逝于此。'],
        ['Huizhou (now Huizhou, Guangdong)', 'Banished to Huizhou in the far south', 'Accused of slandering the late emperor, Su Shi was banished beyond the southern ranges and, close to sixty, crossed the Dayu Pass to Huizhou. There he wrote that with three hundred lychees a day he would gladly remain a southerner, and helped pay for bridges. His companion Wang Zhaoyun died there.']),
      w(1097, 109.58, 19.52,
        ['儋州（今海南儋州）', '贬至海南儋州', '年过六十的苏轼再被贬到海南岛西北部的昌化军（儋州），这在当时是仅次于死刑的重罚。他起初无屋可住，在当地人帮助下盖起茅屋，此后讲学授徒、劝民凿井耕种。'],
        ['Danzhou (now Danzhou, Hainan)', 'Exiled across the sea to Hainan', 'Now past sixty, Su Shi was sent on to Danzhou in north-western Hainan, a punishment then regarded as second only to death. At first he had nowhere to live, and local people helped him build a thatched house. He taught students there and encouraged villagers to dig wells and farm.']),
      w(1101, 119.97, 31.81,
        ['常州', '遇赦北归，病逝于常州', '宋徽宗即位后大赦，苏轼渡海北归，沿途士民争相迎候。他行至常州时一病不起，于1101年8月去世，次年葬于汝州郏城（今河南郏县）。'],
        ['Changzhou (now Changzhou, Jiangsu)', 'Pardoned, he dies on the journey north', 'A general amnesty followed the accession of Emperor Huizong, and Su Shi crossed back to the mainland, greeted by crowds along his route. He fell ill on the way and died at Changzhou in August 1101. He was buried the following year at Jiacheng in Ruzhou (now Jia County, Henan).']),
    ],
    wiki: { zh: '苏轼', en: 'Su Shi' },
  },
  {
    id: 'yue-fei',
    name: { zh: '岳飞', en: 'Yue Fei' },
    birth: 1103, death: 1142,
    title: { zh: '抗金名将', en: 'Southern Song general' },
    region: 'china', lineage: 'china', sprite: 'horse',
    summary: {
      zh: '南宋抗金名将，字鹏举，相州汤阴人。他治军严明，所率“岳家军”屡败金军，有“撼山易，撼岳家军难”之誉。1140年北伐取得郾城大捷，兵锋直指汴京，却被一心求和的宋高宗、秦桧召回（相传连发十二道金牌），次年被解除兵权，随后以“莫须有”的罪名被害。宋孝宗时平反昭雪，后世奉为民族英雄。',
      en: 'Southern Song general, a native of Tangyin in Xiangzhou, who led the defence against the Jurchen Jin dynasty. His strictly disciplined troops, the "Yue Family Army", won repeated victories, and it was said that shaking a mountain was easier than shaking them. In 1140 his northern campaign brought victory at Yancheng and threatened the old capital Kaifeng, but Emperor Gaozong and the chancellor Qin Hui, who were seeking peace, recalled him. He was stripped of command and put to death on an unproven charge. Rehabilitated under Emperor Xiaozong, he has been honoured ever since as a national hero and a model of loyalty.',
    },
    route: [
      w(1103, 114.36, 35.92,
        ['汤阴（今河南汤阴）', '生于相州汤阴', '岳飞生于相州汤阴县的一户农家。据《宋史》记载，他少年时家境贫寒却勤奋好学，尤其喜读《左氏春秋》和孙吴兵法，又随周同学习射箭，能左右开弓。'],
        ['Tangyin (now Tangyin, Henan)', 'Born in Tangyin, Xiangzhou', 'Yue Fei was born to a farming family in Tangyin county. According to the History of Song, he was poor but studious as a boy, fond of the Zuo Commentary and the military classics of Sunzi and Wu Qi, and learned archery from a teacher named Zhou Tong.'],
        { wiki: { zh: '汤阴县', en: 'Tangyin County' } }),
      w(1122, 114.57, 38.15,
        ['真定（今河北正定）', '应募从军', '宋朝联金攻辽，真定府宣抚刘韐招募“敢战士”，十九岁的岳飞应募入伍，被任命为小队长。不久父亲去世，他回乡守丧，第一次军旅生涯就此中断。'],
        ['Zhending (now Zhengding, Hebei)', 'Enlists in the army', 'As the Song joined the Jin in attacking the Liao, the commissioner Liu Ge recruited a corps of volunteers at Zhending. Yue Fei, aged nineteen, enlisted and was made a squad leader. His father died soon afterwards and he went home to observe mourning, cutting short his first spell of service.']),
      w(1126, 114.39, 36.1,
        ['相州（今河南安阳）', '金军南下，再度投军', '金军两度围攻汴京，康王赵构在相州开设大元帅府招兵，岳飞再次投军。相传母亲姚氏在他背上刺下“尽忠报国”四字；《宋史》只记他背有此四字，未说何人所刺。'],
        ['Xiangzhou (now Anyang, Henan)', 'Rejoins the army as the Jin invade', 'With Jin armies besieging Kaifeng, Prince Kang (Zhao Gou) set up a headquarters at Xiangzhou and Yue Fei enlisted again. Tradition holds that his mother tattooed the words "serve the country with utmost loyalty" on his back; the History of Song records the tattoo but not who made it.']),
      w(1127, 115.65, 34.41,
        ['应天府（今河南商丘）', '上书反对南迁，被革职', '汴京陷落、徽钦二帝被掳后，赵构在应天府即位，是为宋高宗。岳飞当时只是低级军官，却上书数千言，反对朝廷南迁、请求北伐，结果以“越职言事”被革除军职。'],
        ['Yingtian Prefecture (now Shangqiu, Henan)', 'Dismissed for a memorial against retreat', 'After Kaifeng fell and two emperors were carried off, Zhao Gou took the throne at Yingtian as Emperor Gaozong. Yue Fei, still a junior officer, submitted a long memorial opposing the court\'s move south and urging a counter-attack. He was dismissed for speaking beyond his rank.']),
      w(1128, 114.31, 34.8,
        ['东京开封府（今河南开封）', '在宗泽麾下守卫开封', '岳飞辗转投到东京留守宗泽部下，在开封周围屡次击退金军，升为统制。宗泽赏识他的勇略，曾授以阵图。1128年宗泽忧愤而逝，继任者措置失当，开封防线逐渐瓦解。'],
        ['Kaifeng (now Kaifeng, Henan)', 'Defends Kaifeng under Zong Ze', 'Yue Fei made his way to the army of Zong Ze, who was holding the old capital, and rose to regimental commander after repeatedly driving back Jin forces around Kaifeng. Zong valued his courage and gave him diagrams of battle formations. After Zong died in 1128 the defence gradually fell apart.']),
      w(1130, 118.78, 32.06,
        ['建康（今江苏南京）', '击败金兀术，收复建康', '金军渡江南侵，一度把宋高宗追到海上。北撤途中，完颜宗弼（兀术）在黄天荡被韩世忠阻截，岳飞又在牛头山和静安镇连败其军，收复建康。岳飞由此独当一面，时年二十七岁。'],
        ['Jiankang (now Nanjing, Jiangsu)', 'Defeats Wuzhu and retakes Jiankang', 'A Jin army crossed the Yangtze and chased Emperor Gaozong out to sea. As it withdrew, its commander Wanyan Zongbi (Wuzhu) was blocked by Han Shizhong at Huangtiandang, and Yue Fei then beat his troops at Niutou Hill and Jing\'an and recovered Jiankang. At twenty-seven he had become an independent commander.']),
      w(1134, 112.14, 32.04,
        ['襄阳（今湖北襄阳）', '收复襄阳等六郡', '岳飞率军渡江北上，三个月内从金朝扶植的伪齐手中夺回郢州、随州、襄阳、邓州、唐州和信阳军，稳住了长江中游的屏障。他因功被授为清远军节度使，时年三十二岁。'],
        ['Xiangyang (now Xiangyang, Hubei)', 'Recovers Xiangyang and five other prefectures', 'Crossing the Yangtze, Yue Fei in three months took back Yingzhou, Suizhou, Xiangyang, Dengzhou, Tangzhou and Xinyang from Qi, the puppet state set up by the Jin, securing the middle Yangtze. He was made a regional military commissioner at the age of thirty-two.']),
      w(1134, 114.3, 30.55,
        ['鄂州（今湖北武汉武昌）', '屯驻鄂州，建立岳家军大本营', '收复襄汉之后，岳飞奉命屯驻鄂州，此后数年这里一直是岳家军的大本营。他治军极严，要求士兵“冻死不拆屋，饿死不掳掠”，军队逐渐扩充，成为南宋最精锐的部队之一。'],
        ['Ezhou (now Wuchang, Wuhan, Hubei)', 'Makes Ezhou the base of his army', 'After the Xiangyang campaign Yue Fei was ordered to garrison Ezhou, which remained his headquarters for years. He enforced strict discipline: his soldiers were to freeze rather than tear down houses for firewood and starve rather than plunder. The army grew into one of the best in the Southern Song.']),
      w(1135, 112.9, 29.2,
        ['洞庭湖（今湖南岳阳、常德一带）', '平定洞庭湖杨幺之乱', '钟相、杨幺的起事已在洞庭湖持续数年，官军屡战屡败。岳飞到后先招降其部众，再以草木堵塞港汊，使对方的车船无法行驶，很快平定全湖，并收编了大批水军。'],
        ['Dongting Lake (near Yueyang and Changde, Hunan)', 'Suppresses the Yang Yao rising on Dongting Lake', 'The rebellion begun by Zhong Xiang and continued by Yang Yao had held Dongting Lake for years and beaten off several government armies. Yue Fei first won over many of the rebels, then choked the channels with floating grass and timber to foul their paddle-wheel boats, and soon ended the rising.'],
        { wiki: { zh: '洞庭湖', en: 'Dongting Lake' } }),
      w(1136, 111.05, 34.05,
        ['虢州卢氏（今河南卢氏）', '北伐伊洛，因粮尽而还', '岳飞自襄阳出兵北伐，部将先后攻克虢州卢氏、商州和伊阳等地，前锋逼近洛阳。由于后方粮草不继、友军未能配合，他只得撤回鄂州。这一年母亲姚氏去世，葬于庐山。'],
        ['Lushi, Guozhou (now Lushi, Henan)', 'Pushes north toward Luoyang, then withdraws', 'Striking north from Xiangyang, Yue Fei\'s officers took Lushi in Guozhou, Shangzhou and Yiyang, and his vanguard approached Luoyang. Short of supplies and unsupported by other armies, he had to pull back to Ezhou. His mother died the same year and was buried on Mount Lu.']),
      w(1140, 114.0, 33.58,
        ['郾城（今河南漯河郾城区）', '郾城、颍昌大捷', '金朝撕毁和约南侵，岳飞挥师北上。完颜宗弼以重甲骑兵“铁浮图”和两翼的“拐子马”突袭郾城，岳家军步兵持麻扎刀、大斧专砍马足，大破金军，数日后又在颍昌再获大胜。'],
        ['Yancheng (now Yancheng District, Luohe, Henan)', 'Victories at Yancheng and Yingchang', 'When the Jin broke the peace and invaded, Yue Fei marched north. Wanyan Zongbi threw his armoured cavalry against Yancheng, but Yue\'s infantry, armed with long blades and axes, hacked at the horses\' legs and routed them. Days later his army won again at Yingchang.'],
        { wiki: { zh: '郾城之战', en: 'Battle of Yancheng' } }),
      w(1140, 114.3, 34.6,
        ['朱仙镇（今河南开封西南）', '进抵朱仙镇，被十二道金牌召回', '据岳珂《金佗稡编》记载，岳家军前锋进抵距汴京仅四十余里的朱仙镇。一心求和的宋高宗与秦桧却严令班师，相传一日之内连发十二道金字牌。岳飞叹道：“十年之功，废于一旦。”'],
        ['Zhuxian Town (south-west of Kaifeng, Henan)', 'Reaches Zhuxian Town and is recalled', 'According to the account compiled by his grandson Yue Ke, Yue Fei\'s vanguard reached Zhuxian Town, about twenty kilometres from Kaifeng. Emperor Gaozong and Qin Hui, intent on peace, ordered him back, by tradition with twelve gold-lettered urgent tablets in one day. Yue lamented that ten years of effort had been undone in a morning.']),
      w(1141, 120.16, 30.27,
        ['临安（今浙江杭州）', '被解除兵权，下大理寺狱', '岳飞与韩世忠、张俊被召到临安，分别改任枢密使、副使，实际上被收回兵权。宋金和议期间，秦桧一党罗织罪名，当年十月岳飞被投入大理寺狱，虽经两个多月审讯仍查无实据。'],
        ['Lin\'an (now Hangzhou, Zhejiang)', 'Stripped of command and imprisoned', 'Yue Fei, Han Shizhong and Zhang Jun were summoned to Lin\'an and given posts in the Bureau of Military Affairs, which removed them from their armies. While peace was being negotiated with the Jin, allies of Qin Hui brought charges against Yue. He was jailed in the tenth month, though two months of interrogation produced no proof.']),
      w(1142, 120.16, 30.27,
        ['临安（今浙江杭州）', '以“莫须有”罪名被杀害', '绍兴十一年除夕（1142年1月27日），岳飞在大理寺狱中被赐死，其子岳云与部将张宪同时被斩。韩世忠质问罪证，秦桧答以“其事体莫须有”。1162年宋孝宗即位后为他平反，改葬西湖栖霞岭。'],
        ['Lin\'an (now Hangzhou, Zhejiang)', 'Put to death on an unproven charge', 'On 27 January 1142 Yue Fei was put to death in prison; his son Yue Yun and his officer Zhang Xian were beheaded. Asked by Han Shizhong for evidence, Qin Hui is said to have replied that there "perhaps was" some. Emperor Xiaozong cleared his name in 1162 and reburied him beside West Lake.'],
        { wiki: { zh: '岳王庙', en: 'Yue Fei Temple' } }),
    ],
    wiki: { zh: '岳飞', en: 'Yue Fei' },
  },
  {
    id: 'saladin',
    name: { zh: '萨拉丁', en: 'Saladin' },
    birth: 1137, death: 1193,
    title: { zh: '阿尤布王朝创建者', en: 'Founder of the Ayyubid dynasty' },
    region: 'west-asia', lineage: 'egypt', sprite: 'horse',
    summary: {
      zh: '埃及与叙利亚的苏丹、阿尤布王朝的创建者，库尔德人，全名萨拉赫丁·优素福·本·阿尤布。他早年随叔父谢尔库赫远征埃及，1171年终结法蒂玛王朝，此后十余年间把埃及、叙利亚和上美索不达米亚统一在自己治下。1187年他在哈丁大败十字军，收复被占据八十八年的耶路撒冷；随后与英格兰国王理查一世率领的第三次十字军相持，1192年议和。他对战败者的宽厚在伊斯兰世界和欧洲的记载中都留下了声名。',
      en: 'Sultan of Egypt and Syria and founder of the Ayyubid dynasty, a Kurd whose full name was Salah ad-Din Yusuf ibn Ayyub. He first went to Egypt on the campaigns of his uncle Shirkuh, ended the Fatimid caliphate in 1171, and over the next decade and a half united Egypt, Syria and Upper Mesopotamia under his rule. In 1187 he destroyed the crusader army at Hattin and recovered Jerusalem after eighty-eight years of Frankish rule. He then fought the Third Crusade, led by Richard I of England, to a negotiated truce in 1192. His generosity toward defeated enemies was noted in both Muslim and European sources.',
    },
    route: [
      w(1137, 43.68, 34.6,
        ['提克里特（今伊拉克提克里特）', '生于底格里斯河畔的提克里特', '萨拉丁出生于一个库尔德军人家庭，父亲纳吉姆丁·阿尤布时任提克里特城堡的长官。据传就在他出生前后，全家因故被迫离开此城，投奔摩苏尔的统治者赞吉。生年一说为1138年。'],
        ['Tikrit (now Tikrit, Iraq)', 'Born at Tikrit on the Tigris', 'Saladin was born into a Kurdish military family; his father, Najm ad-Din Ayyub, commanded the citadel of Tikrit. According to tradition the family had to leave the town around the time of his birth and took service with Zengi, the ruler of Mosul. His birth is also dated to 1138.']),
      w(1139, 36.21, 34.01,
        ['巴勒贝克（今黎巴嫩巴勒贝克）', '随父迁居巴勒贝克', '赞吉攻占巴勒贝克后，任命阿尤布为守将，萨拉丁的童年就在这座耸立着罗马神庙遗迹的城市中度过。赞吉死后，阿尤布转而效力大马士革，全家随之迁往该城。'],
        ['Baalbek (now Baalbek, Lebanon)', 'Childhood in Baalbek', 'After Zengi captured Baalbek he made Ayyub its governor, and Saladin spent his early childhood in the town beside the ruins of its Roman temples. When Zengi died, Ayyub went over to the rulers of Damascus and the family moved there.'],
        { wiki: { zh: '巴勒贝克', en: 'Baalbek' } }),
      w(1154, 36.29, 33.51,
        ['大马士革', '在努尔丁的宫廷中成长', '赞吉之子努尔丁兼并大马士革，萨拉丁的父亲和叔父谢尔库赫都是他倚重的将领。青年萨拉丁在此接受宗教与军事教育，据说擅长马球，后来在叔父手下任职。'],
        ['Damascus', 'Grows up at the court of Nur ad-Din', 'Nur ad-Din, the son of Zengi, added Damascus to his realm, with Saladin\'s father and his uncle Shirkuh among his chief commanders. The young Saladin received a religious and military education there, is said to have been a keen polo player, and entered service under his uncle.']),
      w(1164, 31.56, 30.42,
        ['比勒拜斯（今埃及东部省）', '首次随叔父远征埃及', '法蒂玛王朝的维齐尔沙瓦尔向努尔丁求援，谢尔库赫奉命出兵埃及，萨拉丁随行。沙瓦尔复位后转而联合耶路撒冷国王阿马尔里克，把叙利亚军围困在比勒拜斯约三个月，双方最终议和撤兵。'],
        ['Bilbeis (now in Sharqia, Egypt)', 'First expedition to Egypt with his uncle', 'When the Fatimid vizier Shawar appealed to Nur ad-Din for help, Shirkuh was sent to Egypt and took Saladin with him. Once restored, Shawar allied with King Amalric of Jerusalem, and the Syrian force was besieged in Bilbeis for about three months before both armies agreed to withdraw.']),
      w(1167, 29.92, 31.2,
        ['亚历山大', '坚守亚历山大', '谢尔库赫第二次进军埃及，在巴拜因之战中击退十字军与埃及联军后占领亚历山大，留下萨拉丁率少量兵力守城。他在围困和饥荒中坚持了约两个半月，直到双方达成协议，各自退出埃及。'],
        ['Alexandria', 'Holds Alexandria under siege', 'On a second campaign Shirkuh fought off the combined Frankish and Egyptian army at al-Babein and occupied Alexandria, leaving Saladin to hold it with a small garrison. He endured blockade and hunger for some two and a half months until a settlement let both sides leave Egypt.']),
      w(1169, 31.24, 30.04,
        ['开罗', '出任法蒂玛王朝维齐尔', '十字军再度入侵埃及，谢尔库赫第三次南下并进入开罗，沙瓦尔被处死，谢尔库赫出任维齐尔，两个月后病逝。三十出头的萨拉丁被推举继任，一身兼任什叶派哈里发的大臣和逊尼派努尔丁的部将。'],
        ['Cairo', 'Becomes vizier of the Fatimid caliph', 'When the Franks invaded Egypt again, Shirkuh marched south a third time and entered Cairo. Shawar was put to death and Shirkuh became vizier, only to die two months later. Saladin, in his early thirties, was chosen to succeed him, serving a Shia caliph while remaining an officer of the Sunni Nur ad-Din.']),
      w(1171, 31.24, 30.04,
        ['开罗', '废法蒂玛王朝，建立阿尤布王朝', '萨拉丁下令在聚礼的祈祷词中改颂巴格达的阿拔斯哈里发，数日后末代法蒂玛哈里发阿迪德去世，立国两百余年的法蒂玛王朝就此终结，埃及重归逊尼派。此后他开始修筑开罗城堡和环城城墙。'],
        ['Cairo', 'Ends the Fatimid caliphate and founds his own dynasty', 'Saladin had the Friday sermon in Cairo pronounced in the name of the Abbasid caliph in Baghdad. The last Fatimid caliph, al-Adid, died days later, ending a dynasty of more than two centuries and returning Egypt to Sunni allegiance. Saladin later began the Cairo Citadel and new city walls.']),
      w(1174, 36.29, 33.51,
        ['大马士革', '努尔丁去世，进占大马士革', '努尔丁病逝，继位的儿子年仅十一岁，叙利亚诸将争权。萨拉丁率七百骑兵穿越沙漠，应邀进入大马士革，次年在哈马附近击败赞吉家族的军队，被阿拔斯哈里发承认为埃及和叙利亚的统治者。'],
        ['Damascus', 'Enters Damascus after the death of Nur ad-Din', 'Nur ad-Din died leaving an eleven-year-old heir, and his commanders competed for power. Saladin crossed the desert with seven hundred horsemen and entered Damascus by invitation. The next year he defeated the Zengid forces near Hama, and the Abbasid caliph recognised him as ruler of Egypt and Syria.']),
      w(1177, 34.92, 31.86,
        ['蒙吉萨（今以色列拉姆拉附近）', '在蒙吉萨败于鲍德温四世', '萨拉丁率大军自埃及攻入巴勒斯坦，部队分散劫掠时，遭到年仅十六岁、身患麻风病的耶路撒冷国王鲍德温四世突袭而溃败。他只带少数随从逃回埃及，这是他一生中最惨重的失利之一。'],
        ['Montgisard (near Ramla, Israel)', 'Routed by Baldwin IV at Montgisard', 'Saladin invaded Palestine from Egypt with a large army. While his troops were scattered in search of plunder they were surprised and routed by Baldwin IV, the sixteen-year-old leper king of Jerusalem. Saladin escaped to Egypt with a handful of followers after one of the worst defeats of his career.'],
        { wiki: { zh: '蒙吉萨战役', en: 'Battle of Montgisard' } }),
      w(1183, 37.16, 36.2,
        ['阿勒颇', '取得阿勒颇，统一叙利亚', '经过多年的战争与交涉，赞吉家族的伊马德丁以阿勒颇换取辛贾尔等地，萨拉丁入主这座叙利亚北部的重镇。1186年摩苏尔也承认他的宗主权，从尼罗河到底格里斯河连成一片，十字军诸国陷入三面包围。'],
        ['Aleppo', 'Gains Aleppo and unites Muslim Syria', 'After years of campaigning and bargaining, the Zengid prince Imad ad-Din gave up Aleppo in exchange for Sinjar and other towns, and Saladin took possession of the great city of northern Syria. Mosul accepted his overlordship in 1186, so that his power reached from the Nile to the Tigris and enclosed the crusader states on three sides.'],
        { wiki: { zh: '阿勒颇城堡', en: 'Citadel of Aleppo' } }),
      w(1187, 35.44, 32.8,
        ['哈丁（今以色列太巴列以西）', '哈丁之战全歼十字军主力', '雷纳德袭击商队破坏休战后，萨拉丁围攻太巴列，引诱耶路撒冷王国的军队穿越干旱的高地。7月4日，缺水的十字军在哈丁双角山下被围歼，国王居伊被俘，“真十字架”圣物也落入其手。'],
        ['Hattin (west of Tiberias, Israel)', 'Destroys the crusader army at Hattin', 'After Raynald of Chatillon broke the truce by raiding a caravan, Saladin besieged Tiberias and drew the army of Jerusalem across waterless uplands. On 4 July the thirst-stricken Franks were surrounded and destroyed beneath the Horns of Hattin. King Guy was captured, along with the relic of the True Cross.'],
        { wiki: { zh: '哈丁战役', en: 'Battle of Hattin' } }),
      w(1187, 35.23, 31.78,
        ['耶路撒冷', '收复耶路撒冷', '哈丁之战后，阿卡、雅法、阿什凯隆等城相继陷落。耶路撒冷被围十余日后于10月2日开城投降，萨拉丁允许居民缴纳赎金后离开，没有重演1099年十字军破城时的屠杀。圆顶清真寺上的十字架随即被取下。'],
        ['Jerusalem', 'Recovers Jerusalem', 'After Hattin, Acre, Jaffa, Ascalon and other towns fell in quick succession. Jerusalem surrendered on 2 October after a siege of under two weeks. Saladin let the inhabitants ransom themselves and leave, and there was no repetition of the massacre of 1099. The cross was taken down from the Dome of the Rock.'],
        { wiki: { zh: '圆顶清真寺', en: 'Dome of the Rock' } }),
      w(1191, 35.08, 32.93,
        ['阿卡（今以色列阿卡）', '阿卡围城战失利', '十字军自1189年起围攻阿卡，萨拉丁又在外围反包围，双方相持近两年。法王腓力二世和英王理查一世率援军到达后，守军于1191年7月投降；理查随后下令处死了两千多名穆斯林俘虏。'],
        ['Acre (now Acre, Israel)', 'Loses Acre after a two-year siege', 'The crusaders besieged Acre from 1189 while Saladin in turn blockaded their camp, a deadlock that lasted nearly two years. After Philip II of France and Richard I of England arrived with reinforcements, the garrison surrendered in July 1191. Richard then had more than two thousand Muslim prisoners put to death.']),
      w(1191, 34.81, 32.2,
        ['阿尔苏夫（今以色列荷兹利亚以北）', '阿尔苏夫之战败于理查一世', '理查率军沿海岸南下，萨拉丁一路袭扰，9月7日在阿尔苏夫的林地旁发动总攻。十字军保持密集队形，随后以重骑兵冲锋击溃对手。萨拉丁此后避免正面决战，转而拆毁阿什凯隆等城的城防。'],
        ['Arsuf (north of Herzliya, Israel)', 'Defeated by Richard I at Arsuf', 'As Richard marched south along the coast Saladin harassed his column and on 7 September attacked in force near the woods of Arsuf. The crusaders kept close order and then broke his army with a cavalry charge. Saladin avoided pitched battle afterwards and dismantled the defences of Ascalon and other towns.'],
        { wiki: { zh: '阿尔苏夫战役', en: 'Battle of Arsuf' } }),
      w(1192, 34.75, 32.05,
        ['雅法（今以色列特拉维夫-雅法）', '与理查一世议和', '理查两度逼近耶路撒冷而未敢攻城，萨拉丁夺取雅法的行动也被击退，双方都已精疲力竭。9月订立的和约规定休战三年，提尔至雅法的沿海地带归十字军，耶路撒冷仍由穆斯林管辖，但向基督徒朝圣者开放。'],
        ['Jaffa (now Tel Aviv-Yafo, Israel)', 'Makes peace with Richard I', 'Richard twice approached Jerusalem without daring to besiege it, and Saladin\'s attempt to seize Jaffa was beaten back; both sides were exhausted. The treaty agreed in September set a three-year truce, left the coast from Tyre to Jaffa to the crusaders, and kept Jerusalem under Muslim rule while opening it to Christian pilgrims.']),
      w(1193, 36.29, 33.51,
        ['大马士革', '病逝于大马士革', '和约订立数月后，萨拉丁在大马士革染上热病，于1193年3月4日去世。据其书记官巴哈丁记载，他生前把财产大多施舍给了别人，身后所余不足以支付葬礼费用。他的陵墓位于倭马亚大清真寺旁。'],
        ['Damascus', 'Dies in Damascus', 'A few months after the truce Saladin fell ill with fever in Damascus and died on 4 March 1193. His secretary Baha ad-Din recorded that he had given away most of his wealth and did not leave enough to pay for his funeral. His tomb stands beside the Umayyad Mosque.'],
        { wiki: { zh: '倭马亚大清真寺', en: 'Umayyad Mosque' } }),
    ],
    wiki: { zh: '萨拉丁', en: 'Saladin' },
  },
  {
    id: 'genghis-khan',
    name: { zh: '成吉思汗', en: 'Genghis Khan' },
    birth: 1162, death: 1227, approx: true,
    title: { zh: '大蒙古国创建者', en: 'Founder of the Mongol Empire' },
    region: 'east-asia', lineage: 'mongol', sprite: 'horse',
    summary: {
      zh: '蒙古帝国的缔造者，名铁木真（生年另有1155、1167年等说）。他幼年丧父、历经艰险，逐步统一漠北诸部，1206年被尊为“成吉思汗”。此后率军南下攻金、西夏，又发动第一次西征，攻灭花剌子模，兵锋远达印度河与东欧草原。他建立千户制、颁布《大札撒》，其子孙继续扩张，建立起横跨欧亚的蒙古帝国。',
      en: 'Founder of the Mongol Empire, born Temujin; his birth is also dated to 1155 or 1167. Orphaned young and raised in hardship, he gradually united the tribes of the Mongolian steppe and in 1206 was proclaimed Genghis Khan. He went on to attack the Western Xia and the Jin dynasty in northern China and, in his first western campaign, destroyed the Khwarazmian Empire, his armies reaching the Indus and the steppes of eastern Europe. He organised his people into decimal military units and issued the code known as the Yasa. His descendants extended his conquests into the largest contiguous land empire in history.',
    },
    route: [
      w(1162, 111.6, 49.0,
        ['斡难河畔（今蒙古国肯特省）', '生于斡难河畔，名铁木真', '《蒙古秘史》记载，铁木真生于斡难河畔的迭里温孛勒答黑，出生地与生年都有多种说法。约九岁时，父亲也速该被塔塔儿人毒死，部众离散，母亲诃额仑带着孩子们靠采野果、捕鱼为生。'],
        ['Onon River (now Khentii Province, Mongolia)', 'Born on the Onon River and named Temujin', 'The Secret History of the Mongols places Temujin\'s birth at Deluun Boldog on the Onon, though both the place and the year are disputed. When he was about nine his father Yesugei was poisoned by Tatars; the clan deserted the family, and his mother Hoelun raised her children on wild fruit and fish.']),
      w(1180, 109.0, 48.75,
        ['不儿罕山（今蒙古国肯特山）', '蔑儿乞人来袭，避入不儿罕山', '铁木真娶孛儿帖后不久（约1180年），蔑儿乞人突袭营地，掳走孛儿帖，他逃入不儿罕山才得以脱身。后来他借克烈部首领脱斡邻勒（王汗）和安答札木合之力击败蔑儿乞人，夺回妻子，此后终生祭祀此山。'],
        ['Burkhan Khaldun (Khentii Mountains, Mongolia)', 'Escapes a Merkit raid on Burkhan Khaldun', 'Not long after Temujin married Borte, in about 1180, Merkit raiders fell on his camp and carried her off; he saved himself by fleeing onto Burkhan Khaldun. With the help of Toghrul, khan of the Kereit, and his sworn brother Jamukha he defeated the Merkit and recovered her. He honoured the mountain for the rest of his life.'],
        { wiki: { zh: '不儿罕合勒敦山', en: 'Burkhan Khaldun' } }),
      w(1189, 108.95, 48.02,
        ['青海子（今蒙古国肯特省）', '被推举为蒙古乞颜部的汗', '与札木合分道扬镳后，许多部众前来投奔铁木真。约1189年，乞颜氏的贵族们在古连勒古山中的青海子推举他为汗。他随即设置带弓箭、管饮膳、牧马群等职事，组建起最早的亲信班底。'],
        ['Khokh Nuur, the "Blue Lake" (Khentii Province, Mongolia)', 'Chosen as khan of the Mongol Kiyad', 'After Temujin parted from Jamukha many followers came over to him. In about 1189 the Kiyad nobles raised him as khan at the Blue Lake in the Gurelgu hills. He at once named quiver-bearers, stewards, herders and other officers, forming the first core of his personal following.']),
      w(1203, 117.0, 48.6,
        ['班朱尼河（确切位置不详，一说在呼伦湖附近）', '败于王汗，班朱尼河饮水盟誓', '昔日的盟友王汗突然来袭，铁木真在合兰真沙陀战败，退到班朱尼河时身边只剩少数追随者。相传他与众人同饮浑水，誓言共享富贵。当年秋天他奇袭王汗大营，一举吞并强大的克烈部。'],
        ['Baljuna (site uncertain, possibly near Hulun Lake)', 'Defeated by Toghrul, he regroups at Baljuna', 'His former patron Toghrul, the Ong Khan, turned on Temujin and beat him at Qalaqaljit Sands. He withdrew to Baljuna with only a small band, who by tradition drank its muddy water with him and swore to share whatever fortune came. That autumn he surprised the Ong Khan\'s camp and absorbed the powerful Kereit.']),
      w(1204, 102.5, 47.3,
        ['纳忽崖（今蒙古国杭爱山一带，位置为约略）', '纳忽崖之战，击灭乃蛮', '西面的乃蛮部联合札木合等各部残余来攻。铁木真整编军队，以十户、百户、千户编制，令士兵每人夜间点燃多堆篝火以壮声势，在纳忽崖击溃太阳汗。至此漠北草原上再无可与他抗衡的势力。'],
        ['Naqu Cliff (Khangai Mountains, Mongolia; location approximate)', 'Crushes the Naiman at Naqu Cliff', 'The Naiman of the west gathered Jamukha and the remnants of other tribes against him. Temujin reorganised his army into units of ten, a hundred and a thousand, had each man light several campfires to exaggerate his numbers, and broke the forces of the Tayang Khan. No rival remained on the Mongolian steppe.']),
      w(1206, 108.9, 48.8,
        ['斡难河源（今蒙古国肯特省）', '统一蒙古诸部，称成吉思汗', '铁木真在斡难河源召集忽里勒台大会，竖起九斿白纛，被各部推尊为“成吉思汗”。他把全体牧民编为九十五个千户，分封功臣，扩充怯薛护卫军，并命人用畏兀儿字母书写蒙古语。'],
        ['Source of the Onon River (Khentii Province, Mongolia)', 'Unites the Mongol tribes as Genghis Khan', 'At a great assembly, or kurultai, at the source of the Onon, Temujin raised a white standard with nine tails and was proclaimed Genghis Khan. He divided the whole people into ninety-five units of a thousand under trusted commanders, enlarged his imperial guard and had Mongolian written down in the Uyghur script.'],
        { event: 'genghis-khan-1206' }),
      w(1209, 106.23, 38.47,
        ['中兴府（今宁夏银川）', '进攻西夏，迫其纳女求和', '成吉思汗第三次进攻西夏，围困都城中兴府，引黄河水灌城，不料堤坝溃决反而淹了蒙古军营。西夏国主李安全仍被迫献女请和、岁贡骆驼等物，蒙古由此解除了南下攻金的侧翼之忧。'],
        ['Zhongxing (now Yinchuan, Ningxia)', 'Invades Western Xia and forces its submission', 'On his third campaign against the Tangut state of Western Xia, Genghis Khan besieged its capital and tried to flood it by diverting the Yellow River, but the dykes broke and swamped his own camp. The Xia ruler nevertheless sued for peace, giving a daughter in marriage and tribute, which secured the Mongol flank for war with the Jin.']),
      w(1211, 114.7, 40.95,
        ['野狐岭（今河北张家口万全区）', '大败金军主力', '成吉思汗誓师伐金，越过界壕南下。金朝集结号称数十万的大军扼守野狐岭，蒙古军由木华黎率敢死队冲阵，金军溃退，又在浍河堡遭追歼。金朝的野战精锐在这一战中损失殆尽。'],
        ['Yehuling (now Wanquan, Zhangjiakou, Hebei)', 'Destroys the main Jin field army', 'Genghis Khan declared war on the Jin dynasty and crossed its frontier defences. The Jin massed a very large army at the Yehuling pass, but a charge led by Muqali broke their line and the fleeing troops were cut down again at Huihebao. The best of the Jin field forces were lost in the campaign.'],
        { wiki: { zh: '野狐岭之战', en: 'Battle of Yehuling' } }),
      w(1215, 116.39, 39.91,
        ['中都（今北京）', '蒙古军攻陷金中都', '成吉思汗于1214年兵临中都，金宣宗献上公主和金帛求和，随即迁都汴京。成吉思汗以此为由再度出兵，1215年夏中都粮尽城降，他本人当时驻于塞外，命人前往清点府库。'],
        ['Zhongdu (now Beijing)', 'Mongol forces take the Jin capital Zhongdu', 'Genghis Khan reached Zhongdu in 1214 and withdrew after the Jin emperor offered a princess and treasure, but the court then moved its capital south to Kaifeng. Treating this as a breach, he sent his army back, and the starving city surrendered in summer 1215 while he camped beyond the passes.']),
      w(1219, 68.3, 42.85,
        ['讹答剌（今哈萨克斯坦南部）', '因商队被杀，西征花剌子模', '1218年，蒙古派出的一支数百人的商队在讹答剌被守将亦纳勒术劫杀，前去交涉的使者又遭花剌子模沙摩诃末杀害。成吉思汗亲率大军西征，留察合台、窝阔台围攻此城，数月后城破，守将被处死。'],
        ['Otrar (now in southern Kazakhstan)', 'Marches west against Khwarazm after a caravan massacre', 'In 1218 the governor of Otrar, Inalchuq, seized and killed a Mongol trading caravan of several hundred men, and Shah Muhammad of Khwarazm then put a Mongol envoy to death. Genghis Khan led his army west and left his sons Chagatai and Ogedei to besiege Otrar, which fell after several months.'],
        { wiki: { zh: '讹答剌', en: 'Otrar' } }),
      w(1220, 64.42, 39.77,
        ['布哈拉（今乌兹别克斯坦布哈拉）', '穿越沙漠，攻破布哈拉', '成吉思汗率中军穿过克孜勒库姆沙漠，出其不意地出现在布哈拉城下。守军突围失败后城市投降，内堡则在强攻后陷落。据波斯史家志费尼记载，他曾登上清真寺的讲坛向城中富人训话。'],
        ['Bukhara (now Bukhara, Uzbekistan)', 'Crosses the desert and takes Bukhara', 'Genghis Khan led his central column through the Kyzylkum Desert and appeared without warning before Bukhara. The city surrendered after its garrison failed to break out, and the citadel was stormed. The Persian historian Juvayni relates that he mounted the pulpit of the mosque to address the city\'s notables.']),
      w(1220, 66.96, 39.65,
        ['撒马尔罕（今乌兹别克斯坦撒马尔罕）', '攻陷花剌子模都城撒马尔罕', '花剌子模在都城撒马尔罕驻有重兵，却只守了数日便开城投降。工匠被分赏诸王带往东方，突厥守军遭到屠戮。摩诃末向西逃亡，成吉思汗派哲别、速不台穷追不舍，摩诃末最终死在里海的一座小岛上。'],
        ['Samarkand (now Samarkand, Uzbekistan)', 'Captures the Khwarazmian capital Samarkand', 'Samarkand, the shah\'s capital, held a large garrison but capitulated within days. Its craftsmen were shared out among the Mongol princes and taken east, and the Turkic soldiers were killed. Shah Muhammad fled west, pursued by Jebe and Subutai, and died on an island in the Caspian Sea.']),
      w(1221, 67.83, 34.82,
        ['巴米扬（今阿富汗巴米扬）', '南渡阿姆河，屠巴米扬', '成吉思汗渡过阿姆河，攻取巴尔赫、塔里寒等城，进入兴都库什山区。围攻巴米扬时，他钟爱的孙子、察合台之子木阿秃干中箭身亡，城破后全城被屠，此地后来被称为“恶城”。'],
        ['Bamiyan (now Bamyan, Afghanistan)', 'Crosses the Amu Darya and destroys Bamiyan', 'Genghis Khan crossed the Amu Darya, took Balkh and Talaqan and entered the Hindu Kush. During the siege of Bamiyan his favourite grandson Mutugen, a son of Chagatai, was killed by an arrow. When the town fell its people were massacred, and it was afterwards called the "accursed city".']),
      w(1221, 71.6, 33.0,
        ['印度河畔（今巴基斯坦北部，位置为示意）', '在印度河畔击败扎兰丁', '花剌子模王子扎兰丁在八鲁湾击败一支蒙古军后，成吉思汗亲自追击，在印度河边将其包围。扎兰丁力战不支，纵马跃入河中泅渡而去。相传成吉思汗制止部下放箭，对儿子们称赞他的勇气。'],
        ['Bank of the Indus (northern Pakistan; location approximate)', 'Defeats Jalal ad-Din on the Indus', 'After the Khwarazmian prince Jalal ad-Din beat a Mongol force at Parwan, Genghis Khan pursued him in person and trapped him against the Indus. Overwhelmed, the prince spurred his horse into the river and swam across. Genghis is said to have forbidden his archers to shoot and praised his courage.'],
        { wiki: { zh: '印度河之战', en: 'Battle of the Indus' } }),
      w(1222, 69.2, 35.2,
        ['大雪山行营（今阿富汗兴都库什山，位置为约略）', '在行营会见长春真人丘处机', '全真道士丘处机应召从山东出发，跋涉两年多来到大雪山下的行营。成吉思汗问他有无长生之药，他答以“有卫生之道，而无长生之药”，劝其清心寡欲、敬天爱民。事后全真教获免赋役。'],
        ['Camp in the Hindu Kush (now Afghanistan; location approximate)', 'Receives the Daoist master Qiu Chuji', 'Summoned from Shandong, the Quanzhen Daoist Qiu Chuji travelled for more than two years to reach the khan\'s camp below the Hindu Kush. Asked for an elixir of immortality, he replied that there were ways to preserve life but no such medicine, and urged restraint and care for the people. His order was granted exemption from taxes.'],
        { wiki: { zh: '丘处机', en: 'Qiu Chuji' } }),
      w(1225, 109.0, 47.5,
        ['漠北大斡耳朵（今蒙古国克鲁伦河上游）', '东返蒙古', '成吉思汗沿来路缓缓东归，历时约六年的西征结束。回到漠北的营地后，他把新征服的土地分给诸子：术赤一系得咸海、里海以北的草原，察合台得河中地区，窝阔台得叶密立河一带。'],
        ['Great Ordo in Mongolia (upper Kherlen River)', 'Returns to Mongolia', 'Genghis Khan made his way slowly home, ending a western campaign of some six years. Back at his main camp he assigned the conquered lands among his sons: the line of Jochi received the steppes north of the Aral and Caspian seas, Chagatai Transoxiana, and Ogedei the region around the Emil River.']),
      w(1226, 106.33, 38.1,
        ['灵州（今宁夏灵武）', '最后一次亲征西夏', '西夏不肯送质子，又与金朝修好，成吉思汗最后一次亲征。蒙古军先取黑水城、甘州、肃州、凉州，冬季在冰封的黄河边击溃西夏援军，攻克灵州，随后进围中兴府。'],
        ['Lingzhou (now Lingwu, Ningxia)', 'Last campaign against Western Xia', 'Western Xia had refused to send a hostage prince and made peace with the Jin, so Genghis Khan led a final campaign against it. The Mongols took Khara-Khoto, Ganzhou, Suzhou and Liangzhou, routed a Xia relief army beside the frozen Yellow River in winter, captured Lingzhou and laid siege to the capital.'],
        { wiki: { zh: '黑水城', en: 'Khara-Khoto' } }),
      w(1227, 106.2, 35.7,
        ['六盘山（今宁夏固原）', '征西夏途中病逝', '成吉思汗在六盘山避暑时病重，于1227年8月去世，卒地另有清水县萨里川等说。数日后西夏末主出降被杀，西夏灭亡。遗体被秘密运回漠北安葬，相传葬地在不儿罕山一带，至今未被发现。'],
        ['Liupan Mountains (now Guyuan, Ningxia)', 'Dies during the campaign against Western Xia', 'Genghis Khan fell gravely ill while summering in the Liupan Mountains and died in August 1227; other accounts place his death at Sali Chuan in Qingshui. Days later the last Xia ruler surrendered and was killed. His body was taken secretly to Mongolia and, by tradition, buried near Burkhan Khaldun; the grave has never been found.']),
    ],
    wiki: { zh: '成吉思汗', en: 'Genghis Khan' },
  },
  {
    id: 'kublai-khan',
    name: { zh: '忽必烈', en: 'Kublai Khan' },
    birth: 1215, death: 1294,
    title: { zh: '元朝开国皇帝', en: 'Founding emperor of the Yuan dynasty' },
    region: 'east-asia', lineage: 'mongol', sprite: 'horse',
    summary: {
      zh: '元朝开国皇帝，成吉思汗之孙、拖雷之子。早年受命经略漠南汉地，远征大理。1260年即大汗位，1271年取《易经》“大哉乾元”之义建国号大元，定都大都（今北京）。1279年灭南宋，结束了中国自唐末以来的分裂局面。他推行行省制度，重视农业与驿传交通，贯通京杭大运河，并对日本、安南、爪哇等地发动远征。',
      en: 'Founding emperor of the Yuan dynasty and a grandson of Genghis Khan. As a prince he governed the Chinese lands of the Mongol Empire and conquered the Dali Kingdom. He became Great Khan in 1260 after a disputed succession, adopted the dynastic name Great Yuan in 1271 and made Dadu, now Beijing, his capital. The fall of the Southern Song in 1279 reunited China after centuries of division. He set up the branch secretariats that became provinces, promoted agriculture, the postal relay network and the Grand Canal, and sent expeditions against Japan, Dai Viet and Java.',
    },
    route: [
      w(1215, 109.0, 47.5,
        ['漠北草原（出生地不详，位置为示意）', '生于漠北，成吉思汗之孙', '忽必烈生于1215年9月，是成吉思汗幼子拖雷与唆鲁禾帖尼的第四子，蒙哥之弟、旭烈兀和阿里不哥之兄。出身克烈部的母亲重视教育，为儿子们延请各族老师，他很早就留意中原的治国之道。'],
        ['Mongolian steppe (birthplace unknown; location indicative)', 'Born a grandson of Genghis Khan', 'Kublai was born in September 1215, the fourth son of Tolui, the youngest son of Genghis Khan, and Sorghaghtani Beki. He was a younger brother of Mongke and elder brother of Hulagu and Ariq Boke. His Kereit mother found tutors of many backgrounds for her sons, and he took an early interest in Chinese statecraft.']),
      w(1251, 116.2, 42.4,
        ['金莲川（今内蒙古正蓝旗一带）', '受命总领漠南汉地军国庶事', '兄长蒙哥即大汗位后，把漠南汉地的军政事务交给忽必烈。他在金莲川开府，招揽刘秉忠、姚枢、许衡等汉族士人，在邢州、河南、关中等地试行整顿吏治、劝课农桑，成效显著。'],
        ['Jinlianchuan (near Zhenglan Banner, Inner Mongolia)', 'Given charge of the Chinese lands south of the Gobi', 'When his brother Mongke became Great Khan he entrusted Kublai with the civil and military affairs of North China. From his camp at Jinlianchuan Kublai gathered Chinese advisers such as Liu Bingzhong, Yao Shu and Xu Heng, and tried out administrative and agricultural reforms in Xingzhou, Henan and the Guanzhong region.']),
      w(1253, 106.2, 35.7,
        ['六盘山（今宁夏固原）', '驻军六盘山，会见八思巴', '忽必烈奉命远征大理，在六盘山集结军队。其间他召见年轻的藏传佛教萨迦派领袖八思巴，后来从其受戒。八思巴日后被尊为国师、帝师，并奉命创制了“八思巴字”。'],
        ['Liupan Mountains (now Guyuan, Ningxia)', 'Musters his army and meets Phagpa', 'Ordered to conquer the Dali Kingdom, Kublai assembled his forces in the Liupan Mountains. There he received the young Phagpa, head of the Sakya school of Tibetan Buddhism, from whom he later took initiation. Phagpa went on to become State Preceptor and Imperial Preceptor and devised the Phags-pa script.'],
        { wiki: { zh: '八思巴', en: 'Drogön Chögyal Phagpa' } }),
      w(1253, 100.16, 25.6,
        ['大理（今云南大理）', '远征灭大理国', '大军分三路南下，忽必烈率中路军穿越川西高原，乘革囊和木筏渡过金沙江。大理城破后，他采纳姚枢等人的建议下令禁止屠城，国王段兴智后来归降，仍被委以管理当地。'],
        ['Dali (now Dali, Yunnan)', 'Conquers the Dali Kingdom', 'The army advanced in three columns. Kublai led the centre across the highlands of western Sichuan and crossed the Jinsha River on inflated skins and rafts. When Dali fell he followed the advice of Yao Shu and forbade a massacre. King Duan Xingzhi later submitted and was kept on to administer the region.'],
        { wiki: { zh: '崇圣寺三塔', en: 'Three Pagodas' } }),
      w(1256, 116.18, 42.36,
        ['开平（今内蒙古正蓝旗元上都遗址）', '营建开平城', '忽必烈命刘秉忠在滦河北岸的龙冈选址建城，三年而成，命名开平。城市分宫城、皇城、外城三重，兼有汉式都城的格局和草原行宫的特点。他即位后升开平为上都，每年夏季来此避暑理政。'],
        ['Kaiping (the site of Xanadu, Zhenglan Banner, Inner Mongolia)', 'Builds the city of Kaiping', 'Kublai had Liu Bingzhong choose a site north of the Luan River and build a city, completed in three years and named Kaiping. With its palace, imperial and outer enclosures it combined a Chinese capital plan with a steppe residence. As emperor he made it his summer capital, Shangdu, the Xanadu of European literature.'],
        { wiki: { zh: '元上都', en: 'Shangdu' } }),
      w(1259, 114.3, 30.55,
        ['鄂州（今湖北武汉武昌）', '围攻鄂州，闻蒙哥死讯北返', '蒙哥亲征南宋，命忽必烈率东路军南下。他渡过长江围攻鄂州，久攻不克。此时传来蒙哥在合州钓鱼城下去世、幼弟阿里不哥谋夺汗位的消息，他遂与宋将贾似道议和，匆匆北还。'],
        ['Ezhou (now Wuchang, Wuhan, Hubei)', 'Besieges Ezhou, then turns back on news of Mongke\'s death', 'In Mongke\'s great campaign against the Song, Kublai led the eastern army across the Yangtze and laid siege to Ezhou. Word then came that Mongke had died before Diaoyu Fortress in Sichuan and that their youngest brother Ariq Boke was moving to take the throne. Kublai agreed terms with the Song commander Jia Sidao and hurried north.']),
      w(1260, 116.18, 42.36,
        ['开平（今内蒙古正蓝旗）', '即大汗位', '忽必烈抢先在开平召集支持他的诸王举行忽里勒台，即大汗位，并仿照中原王朝建年号“中统”。一个月后阿里不哥也在哈拉和林称汗，兄弟之间长达四年的内战由此爆发。'],
        ['Kaiping (Zhenglan Banner, Inner Mongolia)', 'Proclaimed Great Khan', 'Kublai forestalled his rival by summoning the princes who backed him to a kurultai at Kaiping, where he was proclaimed Great Khan. Following Chinese practice he adopted a reign title, Zhongtong. A month later Ariq Boke was also proclaimed at Karakorum, and four years of civil war between the brothers began.']),
      w(1264, 116.18, 42.36,
        ['上都（今内蒙古正蓝旗）', '阿里不哥归降，汗位之争结束', '忽必烈控制着中原的粮食和物资，切断了对漠北的供应，阿里不哥屡战失利、众叛亲离，1264年来到上都投降。同年忽必烈改元“至元”，把统治重心南移到燕京。但这场内战也使蒙古帝国走向分裂。'],
        ['Shangdu (Zhenglan Banner, Inner Mongolia)', 'Ariq Boke surrenders, ending the succession war', 'Kublai controlled the grain and goods of North China and cut off supplies to Mongolia. Defeated and deserted by his allies, Ariq Boke came to Shangdu in 1264 and surrendered. Kublai changed his reign title to Zhiyuan and shifted his centre of government to Yanjing, but the war had left the Mongol Empire divided.']),
      w(1267, 116.39, 39.91,
        ['大都（今北京）', '营建大都', '忽必烈决定在金中都旧城东北另建新城，由刘秉忠主持规划，以琼华岛一带的湖泊为中心布置宫城。新城街道纵横如棋盘，历时十余年基本建成，奠定了此后北京城的基本格局。'],
        ['Dadu (now Beijing)', 'Begins building Dadu', 'Kublai decided to build a new city north-east of the old Jin capital. Planned under Liu Bingzhong, it placed the palace beside the lakes around Qionghua Island and laid out streets on a regular grid. Largely finished in under two decades, it set the basic pattern of later Beijing.'],
        { wiki: { zh: '元大都', en: 'Khanbaliq' } }),
      w(1271, 116.39, 39.91,
        ['大都（今北京）', '建国号“大元”', '忽必烈采纳刘秉忠等人的建议，取《易经》“大哉乾元”之义，定国号为“大元”，次年正式把新都命名为大都。他设中书省总理政务，在地方设行中书省，这一行省制度为后世所沿用。'],
        ['Dadu (now Beijing)', 'Proclaims the Great Yuan dynasty', 'On the advice of Liu Bingzhong, Kublai adopted the dynastic name Great Yuan, taken from a phrase in the Book of Changes, and the following year formally named his new capital Dadu. He governed through a Central Secretariat with branch secretariats in the regions, the origin of China\'s later provinces.']),
      w(1276, 116.18, 42.36,
        ['上都（今内蒙古正蓝旗）', '南宋幼帝北上觐见', '伯颜率元军沿长江东下，1276年初兵临临安，谢太后携年幼的宋恭帝出降。恭帝一行被送到上都，忽必烈封他为瀛国公。南宋的残余力量则拥立他的兄弟继续在东南沿海抵抗。'],
        ['Shangdu (Zhenglan Banner, Inner Mongolia)', 'Receives the surrendered Song boy emperor', 'Bayan led the Yuan armies down the Yangtze and reached Lin\'an early in 1276, where Empress Dowager Xie surrendered with the child Emperor Gong. The boy was brought north to Shangdu, and Kublai gave him the title Duke of Ying. Song loyalists enthroned his brothers and fought on along the south-east coast.']),
      w(1279, 116.39, 39.91,
        ['大都（今北京）', '崖山海战后南宋灭亡，统一全国', '1279年3月，张弘范率元军在崖山海面击溃南宋最后的船队，陆秀夫背负幼帝投海。捷报传到大都，自唐末以来延续三百多年的分裂局面结束，元朝成为第一个由北方游牧民族建立的全国性王朝。'],
        ['Dadu (now Beijing)', 'The Song falls at Yamen and China is reunified', 'In March 1279 the Yuan fleet under Zhang Hongfan destroyed the last Song ships off Yamen, and the minister Lu Xiufu leapt into the sea with the boy emperor. When the news reached Dadu, more than three centuries of division since the fall of the Tang were over, and for the first time a steppe dynasty ruled all of China.'],
        { event: 'battle-of-yamen' }),
      w(1287, 120.5, 43.6,
        ['辽河流域（今内蒙古东部，位置为约略）', '亲征辽东，平定乃颜之乱', '东道诸王乃颜联合西北的海都起兵反元。年逾七十的忽必烈亲自率军北上，在辽河一带击败叛军，乃颜被俘后处死。据马可·波罗记述，大汗坐在由大象驮载的木楼上督战。'],
        ['Liao River region (eastern Inner Mongolia; location approximate)', 'Leads the campaign against the rebel prince Nayan', 'Nayan, a prince of the eastern Mongol houses, rebelled in concert with Kaidu in Central Asia. Kublai, now over seventy, took the field himself and defeated the rebels in the Liao River region; Nayan was captured and executed. Marco Polo describes the khan directing the battle from a tower borne by elephants.']),
      w(1293, 116.38, 39.94,
        ['大都积水潭（今北京什刹海）', '通惠河开通，漕船直抵大都', '郭守敬主持开凿的通惠河竣工，京杭大运河全线贯通，江南的粮船可以从杭州直达大都城内。忽必烈从上都回来，路过积水潭，见到水面上船只遮蔽，十分高兴，亲自为这条河命名“通惠河”。'],
        ['Jishuitan, Dadu (now Shichahai, Beijing)', 'The Tonghui Canal brings grain barges into Dadu', 'The Tonghui Canal, engineered by Guo Shoujing, completed the Grand Canal route so that grain barges from Hangzhou could sail into the heart of Dadu. Returning from Shangdu, Kublai passed the Jishuitan basin, saw it crowded with boats, and was so pleased that he named the new waterway himself.'],
        { wiki: { zh: '京杭大运河', en: 'Grand Canal (China)' } }),
      w(1294, 116.39, 39.91,
        ['大都（今北京）', '病逝', '皇后察必和太子真金先后去世，对日本、安南、爪哇的远征又接连失利，忽必烈晚年郁郁寡欢，饮酒无度。1294年2月他在大都去世，在位三十五年，遗体归葬漠北的起辇谷，由孙子铁穆耳继位。'],
        ['Dadu (now Beijing)', 'Dies in Dadu', 'The deaths of Empress Chabi and of his heir Zhenjin, together with failed expeditions against Japan, Dai Viet and Java, clouded Kublai\'s last years, and he drank heavily. He died in Dadu in February 1294 and was taken to Mongolia for burial with his ancestors. His grandson Temur succeeded him.']),
    ],
    wiki: { zh: '忽必烈', en: 'Kublai Khan' },
  },
  {
    id: 'marco-polo',
    name: { zh: '马可·波罗', en: 'Marco Polo' },
    birth: 1254, death: 1324,
    title: { zh: '旅行家、商人', en: 'Merchant and traveller' },
    region: 'europe', sprite: 'camel',
    summary: {
      zh: '威尼斯商人、旅行家。1271年随父亲和叔父东行，经波斯、帕米尔和河西走廊，于1275年抵达元朝上都，据其游记记载曾在元廷任职十七年。1291年前后护送公主由海路西返，1295年回到威尼斯，后在热那亚狱中口述《马可·波罗游记》，书中对中国富庶繁华的描述激发了欧洲人对东方的向往。游记部分内容的真实性在学界尚有讨论。',
      en: 'Venetian merchant and traveller. In 1271 he set out with his father and uncle across Persia, the Pamirs and the Hexi Corridor, reaching the court of Kublai Khan at Shangdu in 1275; by his own account he served the khan for seventeen years. He returned by sea escorting a Mongol princess to Persia and was back in Venice in 1295. Captured in a war with Genoa, he dictated in prison the book known as The Travels of Marco Polo, whose picture of a wealthy and populous China fed European curiosity about the East for centuries. Scholars still debate the accuracy of parts of it.',
    },
    route: [
      w(1254, 12.34, 45.44,
        ['威尼斯', '生于威尼斯商人家庭', '马可·波罗出生时，父亲尼科洛和叔父马费奥正在东方经商，后来一直走到忽必烈的宫廷。马可由亲戚抚养长大，直到1269年两位长辈带着大汗致教宗的书信回到威尼斯，十五岁的他才第一次见到父亲。'],
        ['Venice', 'Born into a Venetian merchant family', 'When Marco Polo was born his father Niccolo and uncle Maffeo were away trading in the East, a journey that eventually took them to the court of Kublai Khan. Raised by relatives, Marco first met his father at fifteen, when the brothers returned to Venice in 1269 carrying the khan\'s letters for the pope.']),
      w(1271, 35.08, 32.93,
        ['阿卡（今以色列阿卡）', '随父亲和叔父启程东行', '十七岁的马可随父亲和叔父从威尼斯乘船到十字军控制的港口阿卡。他们到耶路撒冷圣墓教堂取了忽必烈索要的灯油，又从刚当选教宗的格里高利十世那里领到复信，两名随行的修士却在半路折返。'],
        ['Acre (now Acre, Israel)', 'Sets out for the East with his father and uncle', 'Aged seventeen, Marco sailed with his father and uncle from Venice to the crusader port of Acre. They fetched oil from the lamp of the Holy Sepulchre in Jerusalem, as Kublai had asked, and received letters from the newly elected Pope Gregory X. The two friars sent with them soon turned back.'],
        { sea: true, via: [[19.0, 40.0], [24.0, 35.5], [32.0, 33.5]] }),
      w(1271, 35.79, 36.77,
        ['阿亚斯（今土耳其尤穆尔塔勒克）', '在阿亚斯登陆，踏上陆路', '波罗一家从阿卡渡海到小亚美尼亚王国的港口阿亚斯（拉亚佐），这里是当时地中海通往亚洲内陆的主要门户，香料和丝绸在此转运。他们由此北上，穿过安纳托利亚东部和亚美尼亚高原。'],
        ['Ayas (now Yumurtalik, Turkey)', 'Lands at Ayas and takes the overland road', 'From Acre the Polos crossed to Ayas, or Laiazzo, the port of the Armenian kingdom of Cilicia and then the main Mediterranean gateway to inner Asia, where spices and silks changed hands. From there they travelled north through eastern Anatolia and the Armenian highlands.'],
        { sea: true, via: [[35.3, 35.0], [35.6, 36.4]] }),
      w(1272, 46.29, 38.08,
        ['大不里士（今伊朗大不里士）', '途经伊儿汗国都城大不里士', '一行人进入蒙古伊儿汗国，到达其都城大不里士。马可在书中称这里商贾云集，来自巴格达、印度和霍尔木兹的货物汇聚于此，当地出产的金线织锦和丝绸尤为名贵。此后他们向东南穿过波斯高原。'],
        ['Tabriz (now Tabriz, Iran)', 'Passes through Tabriz, capital of the Ilkhanate', 'The travellers entered the Mongol Ilkhanate and reached its capital, Tabriz. Marco describes a city crowded with merchants, where goods from Baghdad, India and Hormuz met and where costly cloths of silk and gold were woven. From there they turned south-east across the Persian plateau.']),
      w(1272, 56.27, 27.1,
        ['霍尔木兹（今伊朗霍尔木兹海峡北岸）', '原拟从海路东行，后改走陆路', '波罗一家经亚兹德、克尔曼来到波斯湾口的霍尔木兹，本想由此乘船去中国。但看到当地的船只不用铁钉、只用椰索缝合，他们认为太不安全，于是折回克尔曼，改走陆路向东北行进。'],
        ['Hormuz (on the Strait of Hormuz, Iran)', 'Plans to go by sea, then turns back overland', 'By way of Yazd and Kerman the Polos reached Hormuz at the mouth of the Persian Gulf, intending to take ship for China. Finding that the local vessels were stitched together with coconut-fibre cord rather than nailed, they judged them unsafe, returned to Kerman and struck north-east by land.']),
      w(1273, 66.9, 36.76,
        ['巴尔赫（今阿富汗巴尔赫）', '经呼罗珊至巴尔赫', '穿过呼罗珊的荒漠后，他们到达巴尔赫。马可称它曾是一座宏伟的大城，有许多大理石宫殿，但已被鞑靼人摧毁，满目废墟。继续东行到巴达赫尚时他患了病，据说在山区休养了约一年才康复。'],
        ['Balkh (now Balkh, Afghanistan)', 'Crosses Khorasan to Balkh', 'After the deserts of Khorasan the party reached Balkh, which Marco calls a once splendid city of marble palaces left in ruins by the Tartars. Further east, in Badakhshan, he fell ill and is said to have spent about a year recovering in the mountain air.']),
      w(1273, 73.5, 37.5,
        ['帕米尔高原', '翻越帕米尔高原', '他们沿瓦罕河谷登上帕米尔。马可记述这里地势极高，走上十二天不见人烟和飞鸟，火焰因寒冷而不旺，煮食物也不易熟；高原上有一种长着巨角的野羊，后来被命名为“马可·波罗盘羊”。'],
        ['Pamir Mountains', 'Crosses the Pamirs', 'Following the Wakhan valley they climbed onto the Pamirs. Marco reports twelve days without a dwelling or a bird, and fires that burned poorly and cooked food slowly in the cold, thin air. The great-horned wild sheep he saw there was later named the Marco Polo sheep.'],
        { wiki: { zh: '帕米尔高原', en: 'Pamir Mountains' } }),
      w(1274, 75.99, 39.47,
        ['可失合儿（今新疆喀什）', '进入塔里木盆地', '下了帕米尔，波罗一家来到塔里木盆地西端的绿洲喀什。马可提到这里有美丽的园林和葡萄园，盛产棉花，居民以经商和手工业为生，城中除穆斯林外还有一些聂斯托利派基督徒和他们的教堂。'],
        ['Kashgar (now Kashgar, Xinjiang)', 'Enters the Tarim Basin', 'Descending from the Pamirs, the Polos came to the oasis of Kashgar at the western end of the Tarim Basin. Marco mentions fine gardens and vineyards, abundant cotton and a population living by trade and crafts, including some Nestorian Christians with churches of their own.']),
      w(1274, 79.92, 37.11,
        ['忽炭（今新疆和田）', '沿昆仑山北麓东行', '一行人沿塔克拉玛干沙漠南缘、昆仑山北麓的绿洲一路向东，经过莎车、和田、且末。马可记载和田物产丰饶，附近河流中出产碧玉和玉髓；再往东到罗布，旅人要在那里备足一个月的粮草才能穿越大漠。'],
        ['Khotan (now Hotan, Xinjiang)', 'Travels east along the foot of the Kunlun', 'The party moved from oasis to oasis along the southern edge of the Taklamakan Desert, through Yarkand, Khotan and Cherchen. Marco notes Khotan\'s abundance and the jasper and chalcedony found in nearby rivers. Further on, at Lop, travellers rested and took on a month\'s provisions before crossing the desert.']),
      w(1274, 94.66, 40.14,
        ['沙州（今甘肃敦煌）', '进入河西走廊', '穿越罗布泊一带的沙漠约需三十天，马可记下了旅人夜间听到“鬼魂”呼唤而迷路的传说。出了沙漠便是沙州，他注意到这里的居民多信佛教，寺庙里供奉着许多佛像，并描述了当地的丧葬习俗。'],
        ['Shazhou (now Dunhuang, Gansu)', 'Enters the Hexi Corridor', 'The desert crossing beyond Lop took about thirty days, and Marco records tales of spirit voices that lured travellers off the track at night. On the far side lay Shazhou, where he noted that most people were Buddhists with many temples and images, and described their funeral customs.'],
        { wiki: { zh: '敦煌市', en: 'Dunhuang' } }),
      w(1274, 100.45, 38.93,
        ['甘州（今甘肃张掖）', '在甘州停留约一年', '波罗一家在河西走廊的重镇甘州因事停留了约一年。马可在书中描写城里寺院中巨大的卧佛，周围环绕着许多小像。张掖大佛寺的卧佛建于西夏时期，至今尚存。'],
        ['Ganzhou (now Zhangye, Gansu)', 'Stays about a year in Ganzhou', 'The Polos were detained by their affairs for about a year in Ganzhou, a major town of the Hexi Corridor. Marco describes huge reclining Buddhas in its monasteries, surrounded by smaller figures. The reclining Buddha of the Giant Buddha Temple in Zhangye, made under the Western Xia, survives today.']),
      w(1275, 116.18, 42.36,
        ['上都（今内蒙古正蓝旗）', '抵达元上都，觐见忽必烈', '离开威尼斯三年半之后，波罗一家抵达忽必烈的夏都上都，呈上教宗的书信和圣墓的灯油。马可笔下的上都有大理石宫殿和一座可以拆卸的竹殿，周围是放养着鹿群的御苑。'],
        ['Shangdu (Xanadu; Zhenglan Banner, Inner Mongolia)', 'Reaches Shangdu and is presented to Kublai Khan', 'Three and a half years after leaving Venice the Polos arrived at Kublai\'s summer capital and delivered the pope\'s letters and the oil from the Holy Sepulchre. Marco describes a marble palace, a pavilion of cane that could be taken apart, and a walled park stocked with deer.'],
        { wiki: { zh: '元上都', en: 'Shangdu' } }),
      w(1276, 116.39, 39.91,
        ['大都（汗八里，今北京）', '据记载在元朝任职十七年，游历各地', '据游记所述，马可学会了几种语言，深得忽必烈信任，多次奉命出使各地。他详细描写了汗八里的宫殿和棋盘状的街道、新年朝贺与狩猎、通行全国的纸币、驿站，以及当地人用来取暖的“黑石头”——煤。'],
        ['Dadu (Khanbaliq, now Beijing)', 'Said to have served the khan for seventeen years', 'By his own account Marco learned several languages, won Kublai\'s confidence and was sent on missions around the empire. He describes Khanbaliq\'s palace and grid of streets, the New Year feast and the hunts, paper money, the relay-post system and the black stones burned for heat, which were coal.']),
      w(1278, 102.71, 25.04,
        ['押赤（今云南昆明）', '据游记，奉使云南', '书中说马可的第一次出使是去遥远的“哈剌章”（云南），时间约在13世纪70年代末。他从大都出发，过卢沟桥，经太原、京兆（西安）、成都入滇，记下了当地以海贝为货币、用盐块交易和捕捉“大蛇”（鳄鱼）的见闻。'],
        ['Yachi (now Kunming, Yunnan)', 'Travels to Yunnan on a mission, by his account', 'The book says Marco\'s first mission, probably in the late 1270s, took him to distant Carajan, or Yunnan. Leaving Dadu by the bridge over the Lugou River, he went by Taiyuan, Xi\'an and Chengdu, and reported cowrie shells used as money, trade in blocks of salt and the hunting of great "serpents", evidently crocodiles.'],
        { wiki: { zh: '卢沟桥', en: 'Marco Polo Bridge' } }),
      w(1282, 119.42, 32.39,
        ['扬州', '自称曾在扬州任职三年', '游记称马可曾奉大汗之命治理扬州三年，但各抄本说法不一，中文史料中也找不到相应记载，学者多持怀疑态度，年份亦不可考。可以确定的是，扬州在元代确有意大利商人居住，当地出土过14世纪的拉丁文墓碑。'],
        ['Yangzhou (now Yangzhou, Jiangsu)', 'Claims to have held office in Yangzhou for three years', 'The book states that Marco governed Yangzhou for three years by the khan\'s order, but manuscripts differ, Chinese records are silent and most scholars doubt the claim; the dates are unknown. Italians certainly did live in Yuan Yangzhou, where fourteenth-century Latin tombstones have been found.']),
      w(1290, 120.16, 30.27,
        ['行在（今浙江杭州）', '书中盛赞“行在”杭州', '马可把南宋故都杭州称为“行在”，誉之为世界上最华美的“天城”。他描写了城中纵横的运河与无数石桥、十个大市场、西湖上的游船和每日消耗的大量胡椒，这些章节是全书最细致的部分之一。'],
        ['Quinsai (now Hangzhou, Zhejiang)', 'Praises Hangzhou, the "Quinsai" of his book', 'Marco calls the former Song capital Quinsai and declares it the finest and noblest city in the world. He describes its canals and countless stone bridges, ten great market squares, pleasure boats on West Lake and the quantity of pepper consumed each day, in some of the most detailed chapters of the book.']),
      w(1291, 118.58, 24.87,
        ['刺桐（今福建泉州）', '护送阔阔真公主远嫁，自泉州启航', '伊儿汗阿鲁浑遣使向元廷求婚，忽必烈选定阔阔真公主。波罗一家熟悉海路，获准随行护送，借机返乡。船队由十四艘大船组成，从刺桐出发；马可称这里是世界上最大的港口之一，胡椒的进口量远超亚历山大。'],
        ['Zaiton (now Quanzhou, Fujian)', 'Sails from Quanzhou escorting Princess Kokochin', 'When the Ilkhan Arghun sent to the Yuan court for a bride, Kublai chose Princess Kokochin. The Polos, familiar with the sea route, were allowed to accompany her and so go home. A fleet of fourteen large ships left Zaiton, which Marco calls one of the greatest ports in the world.'],
        { wiki: { zh: '泉州市', en: 'Quanzhou' } }),
      w(1292, 97.5, 5.2,
        ['苏门答腊岛北部（须文达那）', '在苏门答腊候风五个月', '船队经占城和马六甲海峡到达苏门答腊岛北部，为等待季风停留了五个月。一行人上岸挖壕筑寨以防当地人袭击。马可注意到在这里已经看不到北极星，并记下了西米、椰子酒和犀牛等见闻。'],
        ['Northern Sumatra (Samudra)', 'Waits five months in Sumatra for the monsoon', 'By way of Champa and the Strait of Malacca the fleet reached northern Sumatra, where it waited five months for the monsoon. The travellers camped ashore behind a ditch and stockade for fear of the inhabitants. Marco noted that the Pole Star could no longer be seen, and described sago, palm wine and the rhinoceros.'],
        { sea: true, via: [[114.0, 18.0], [109.0, 9.0], [104.5, 1.4], [100.0, 3.5]] }),
      w(1293, 56.27, 27.1,
        ['霍尔木兹（今伊朗霍尔木兹海峡北岸）', '抵达波斯', '船队途经锡兰和印度西南海岸，马可记下了采珠、宝石和胡椒贸易。航程历时两年左右，损失惨重，据称出发时的数百名乘客只有少数生还。此时阿鲁浑已经去世，公主后来嫁给了他的儿子合赞。'],
        ['Hormuz (on the Strait of Hormuz, Iran)', 'Arrives in Persia', 'The fleet called at Ceylon and the south-west coast of India, where Marco recorded pearl fishing, gems and the pepper trade. The voyage took some two years and, by his account, only a few of the several hundred passengers survived. Arghun had died meanwhile, and the princess was married to his son Ghazan.'],
        { sea: true, via: [[90.0, 6.0], [80.0, 5.6], [74.0, 11.0], [63.0, 23.0]] }),
      w(1294, 46.29, 38.08,
        ['大不里士（今伊朗大不里士）', '在伊儿汗国停留数月', '把公主交给合赞之后，波罗一家来到大不里士，在当时的伊儿汗海合都的宫廷停留了约九个月，并获赠通行全境的金牌。在这里他们得知忽必烈已经去世，重返东方再无可能。'],
        ['Tabriz (now Tabriz, Iran)', 'Spends some months in the Ilkhanate', 'After delivering the princess to Ghazan, the Polos went to Tabriz and stayed about nine months at the court of the reigning Ilkhan, Gaykhatu, who gave them golden tablets of safe conduct. There they learned that Kublai Khan had died, and with him any prospect of returning east.']),
      w(1295, 39.72, 41.0,
        ['特拉布宗（今土耳其特拉布宗）', '经特拉布宗抵达黑海', '波罗一家向西北穿过亚美尼亚高原，来到黑海南岸的特拉布宗帝国。据马可叔父马费奥的遗嘱记载，他们在这里被当地官府夺去了价值约四千枚拜占庭金币的财物，随后才乘船西去。'],
        ['Trebizond (now Trabzon, Turkey)', 'Reaches the Black Sea at Trebizond', 'The Polos crossed the Armenian highlands north-west to the Empire of Trebizond on the southern shore of the Black Sea. According to the will of Marco\'s uncle Maffeo, the authorities there relieved them of goods worth about four thousand Byzantine gold coins before they could take ship for the west.']),
      w(1295, 28.98, 41.01,
        ['君士坦丁堡（今土耳其伊斯坦布尔）', '渡黑海至君士坦丁堡', '他们乘船沿黑海南岸西行，穿过博斯普鲁斯海峡到达君士坦丁堡。三十多年前，马可的父亲和叔父正是从这座城市的威尼斯商站出发前往东方的。一行人由此经爱琴海上的内格罗蓬特返回威尼斯。'],
        ['Constantinople (now Istanbul, Turkey)', 'Crosses the Black Sea to Constantinople', 'The Polos sailed west along the southern shore of the Black Sea and through the Bosporus to Constantinople, from whose Venetian trading quarter Marco\'s father and uncle had first set out for the East more than thirty years before. From there they went on by Negroponte in the Aegean to Venice.'],
        { sea: true, via: [[37.0, 41.6], [35.2, 42.4], [32.5, 42.2], [30.0, 41.5], [29.15, 41.3]] }),
      w(1295, 12.34, 45.44,
        ['威尼斯', '回到阔别二十四年的故乡', '波罗一家离乡二十四年后回到威尼斯。相传亲友已认不出这三个衣衫褴褛、口音怪异的人，直到他们在宴席上拆开旧衣的夹缝，倒出大量宝石。这个故事出自16世纪的记载，未必可信。'],
        ['Venice', 'Returns home after twenty-four years', 'The Polos reached Venice twenty-four years after leaving it. A story first recorded in the sixteenth century, and not necessarily reliable, tells that their relatives failed to recognise the three ragged travellers until, at a banquet, they slit open the seams of their old clothes and poured out a hoard of jewels.'],
        { sea: true, via: [[27.6, 40.75], [26.7, 40.42], [26.2, 40.05], [25.2, 38.8], [24.2, 37.3], [23.0, 36.2], [21.4, 36.5], [19.5, 39.0], [18.8, 40.3], [16.5, 42.3], [13.6, 44.6]] }),
      w(1298, 8.93, 44.41,
        ['热那亚', '海战被俘，在狱中口述游记', '威尼斯与热那亚交战，马可在一次海战中被俘（传统说法是1298年的库尔佐拉海战），关押在热那亚。狱中他向同囚的比萨作家鲁斯蒂谦讲述东方见闻，后者用法语-意大利混合语笔录成书，即《马可·波罗游记》。'],
        ['Genoa', 'Captured at sea, he dictates his book in prison', 'During a war between Venice and Genoa, Marco was taken prisoner in a naval engagement, traditionally the battle of Curzola in 1298, and held in Genoa. There he related his travels to a fellow captive, the romance writer Rustichello of Pisa, who wrote them down in Franco-Italian as the book now known as The Travels of Marco Polo.'],
        { wiki: { zh: '马可·波罗游记', en: 'The Travels of Marco Polo' } }),
      w(1324, 12.34, 45.44,
        ['威尼斯', '病逝', '马可获释后回到威尼斯，娶妻多纳塔，育有三个女儿，继续经商，生活富足。1324年1月他在病中立下遗嘱，随后去世，葬于圣洛伦佐教堂。相传临终时有人劝他收回书中的夸张之词，他回答说：“我所见的，还没有说出一半。”'],
        ['Venice', 'Dies in Venice', 'Released in 1299, Marco returned to Venice, married Donata Badoer, had three daughters and prospered as a merchant. He made his will in January 1324 and died soon afterwards, and was buried at the church of San Lorenzo. He is said to have insisted on his deathbed that he had not told half of what he saw.']),
    ],
    wiki: { zh: '马可·波罗', en: 'Marco Polo' },
  },
  {
    id: 'mansa-musa',
    name: { zh: '曼萨·穆萨', en: 'Mansa Musa' },
    birth: 1280, death: 1337, approx: true,
    title: { zh: '马里帝国君主', en: 'Ruler of the Mali Empire' },
    region: 'africa', sprite: 'camel',
    summary: {
      zh: '西非马里帝国的君主（“曼萨”），约1312年至1337年在位。在他治下，马里的疆域从大西洋沿岸延伸到尼日尔河中游的加奥，控制着撒哈拉商路南端的黄金产地。1324至1325年他率庞大队伍经开罗前往麦加朝觐，沿途大量施舍黄金，使马里之名传遍伊斯兰世界和欧洲。归国后他延请学者和建筑师，在廷巴克图等地兴建清真寺，推动了伊斯兰学术在西非的发展。生卒年均为约数。',
      en: 'Ruler, or mansa, of the Mali Empire in West Africa from about 1312 to about 1337. Under him Mali reached from the Atlantic coast to Gao on the middle Niger and controlled the goldfields at the southern end of the trans-Saharan trade routes. In 1324-25 he made the pilgrimage to Mecca by way of Cairo with an enormous retinue, giving away so much gold that reports of Mali\'s wealth spread across the Islamic world and into Europe. On his return he brought scholars and an architect with him and built mosques at Timbuktu and elsewhere, encouraging Islamic learning in West Africa. His dates are approximate.',
    },
    route: [
      w(1280, -8.38, 11.38,
        ['尼亚尼（今几内亚东北部，出生地不详）', '生于马里帝国王族', '穆萨约生于1280年，属马里帝国的凯塔王族，“曼萨”意为君主。他的确切出生地没有记载，这里以传统认定的都城尼亚尼示意。帝国由松迪亚塔在13世纪创立，控制着尼日尔河上游的金矿与商路。'],
        ['Niani (north-eastern Guinea; birthplace unknown)', 'Born into the royal house of Mali', 'Musa was born around 1280 into the Keita ruling family of Mali; mansa is the title of its kings. His birthplace is not recorded and is shown here at Niani, the traditional capital. The empire, founded by Sunjata in the thirteenth century, controlled the goldfields and trade routes of the upper Niger.']),
      w(1312, -8.38, 11.38,
        ['尼亚尼（今几内亚东北部）', '继位为马里曼萨', '穆萨约在1312年继位。据埃及学者乌马里转述，穆萨自称前任君主不信大洋没有尽头，率大批船只驶入大西洋后一去不返，他本是留守的摄政，由此登上王位。这段说法只有这一处记载。'],
        ['Niani (north-eastern Guinea)', 'Becomes mansa of Mali', 'Musa came to the throne around 1312. As reported by the Egyptian scholar al-Umari, he said that his predecessor, unwilling to believe the ocean had no end, had sailed into the Atlantic with a great fleet and never returned, leaving Musa, his deputy, to rule. The story rests on this single account.']),
      w(1324, -7.03, 17.3,
        ['瓦拉塔（今毛里塔尼亚东南部）', '率庞大队伍北上朝觐', '穆萨把国事交给儿子，率朝觐队伍北上，在撒哈拉南缘的商站瓦拉塔进入沙漠。后世的阿拉伯文和西非史书说随行者有数万人，上百头骆驼驮着黄金，这些数字各书不一，难以核实，但队伍规模之大并无疑问。'],
        ['Walata (now in south-eastern Mauritania)', 'Sets out north on the pilgrimage', 'Leaving his son to govern, Musa led his pilgrim caravan north and entered the desert at Walata, a trading post on the southern edge of the Sahara. Later Arabic and West African chronicles speak of tens of thousands of followers and a hundred camel-loads of gold. The figures vary and cannot be checked, but the scale was clearly exceptional.']),
      w(1324, 0.27, 27.87,
        ['图瓦特绿洲（今阿尔及利亚阿德拉尔一带）', '穿越撒哈拉，经图瓦特绿洲', '队伍沿商道穿过撒哈拉，到达沙漠中部的图瓦特绿洲群。据17世纪廷巴克图的《苏丹史》记载，许多随行者在这里患上足疾，无法继续前行，便留居当地。此后队伍折向东北，前往埃及。'],
        ['Tuat oases (around Adrar, Algeria)', 'Crosses the Sahara by the Tuat oases', 'The caravan followed the trade road across the Sahara to the oases of Tuat in the central desert. According to the Tarikh al-Sudan, written in Timbuktu in the seventeenth century, many of the party were struck there by a foot ailment, could go no further and settled in the oases. The rest turned north-east for Egypt.']),
      w(1324, 31.24, 30.04,
        ['开罗', '抵达开罗，挥金如土', '1324年7月，穆萨抵达开罗，先在金字塔旁扎营三日，随后会见马穆鲁克苏丹纳西尔·穆罕默德。他在城中大量采购和施舍，把黄金赠给官员和穷人。乌马里十余年后到访时听说，开罗的金价因此下跌，多年未能恢复。'],
        ['Cairo', 'Reaches Cairo and scatters gold', 'Musa arrived in Cairo in July 1324, camped for three days beside the Pyramids and then met the Mamluk sultan al-Nasir Muhammad. He spent and gave away gold freely to officials and the poor. Al-Umari, visiting more than a decade later, was told that the price of gold in Cairo had fallen and not yet recovered.'],
        { event: 'mansa-musa-hajj' }),
      w(1324, 39.83, 21.42,
        ['麦加', '在麦加完成朝觐', '穆萨随埃及的朝觐驼队出发，经西奈半岛和红海东岸南下，于伊斯兰历724年末（公历1324年底）在麦加完成朝觐。他在圣地继续布施，并邀请几位圣裔、学者和安达卢西亚诗人萨希利随他返回马里。'],
        ['Mecca', 'Performs the hajj at Mecca', 'Musa travelled with the Egyptian pilgrim caravan across Sinai and down the eastern shore of the Red Sea, and performed the hajj at the end of the Islamic year 724, late in 1324. He continued his almsgiving in the holy city and invited several descendants of the Prophet, scholars and the Andalusian poet al-Sahili to return with him to Mali.'],
        { via: [[32.55, 29.97], [35.0, 29.53], [36.45, 26.23], [38.06, 24.09]], wiki: { zh: '克尔白', en: 'Kaaba' } }),
      w(1325, 31.24, 30.04,
        ['开罗', '返抵开罗，举债购书', '归途中穆萨的队伍与大队失散，在寒冷和饥渴中损失了不少人。回到开罗时他带来的黄金已经用尽，只得向当地商人高息借贷。他仍购置了大批伊斯兰教法书籍，准备带回国内。'],
        ['Cairo', 'Returns to Cairo and borrows to buy books', 'On the way back Musa\'s party became separated from the main caravan and lost many people to cold and thirst. By the time he reached Cairo his gold was spent and he had to borrow from local merchants at high interest. He nevertheless bought a large number of books on Islamic law to take home.'],
        { via: [[38.06, 24.09], [36.45, 26.23], [35.0, 29.53], [32.55, 29.97]] }),
      w(1325, 9.5, 30.13,
        ['加达梅斯（今利比亚西部）', '归途经加达梅斯绿洲', '穆萨离开埃及后取道的黎波里塔尼亚内陆西归。据伊本·赫勒敦记载，他在撒哈拉北缘的加达梅斯绿洲接见了一位前来求援的北非首领，并带他同行。此后队伍再度南穿大漠，前往尼日尔河湾。'],
        ['Ghadames (now in western Libya)', 'Returns by the oasis of Ghadames', 'Leaving Egypt, Musa travelled west through the interior of Tripolitania. Ibn Khaldun records that at the oasis of Ghadames, on the northern edge of the Sahara, he received a North African chieftain seeking his support, who joined the caravan as it turned south across the desert toward the Niger bend.']),
      w(1325, -0.04, 16.27,
        ['加奥（今马里加奥）', '巡视新归附的加奥', '穆萨朝觐期间，他的将领攻占了尼日尔河中游的桑海都城加奥。据《苏丹史》记载，穆萨归途中特意绕道此城接受归顺，在城中修建了一座清真寺，并把两名桑海王子带回宫廷作为人质。'],
        ['Gao (now Gao, Mali)', 'Visits newly subdued Gao', 'While Musa was on pilgrimage one of his generals took Gao, the Songhai capital on the middle Niger. According to the Tarikh al-Sudan, Musa went out of his way on the journey home to receive its submission, had a mosque built there and took two Songhai princes back to his court as hostages.']),
      w(1325, -3.0074, 16.7666,
        ['廷巴克图（今马里通布图）', '在廷巴克图兴建津加里贝尔清真寺', '穆萨溯尼日尔河西行，到达此时已归属马里的廷巴克图。他命萨希利在此修建王室住所和津加里贝尔大清真寺，后者约在1327年建成，以泥砖和木梁筑成，历经多次重修保存至今。廷巴克图日后成为西非的学术中心。'],
        ['Timbuktu (now Tombouctou, Mali)', 'Builds the Djinguereber Mosque at Timbuktu', 'Travelling up the Niger, Musa reached Timbuktu, by now under Malian rule. He had al-Sahili build a royal residence and the great Djinguereber Mosque, finished around 1327 in mud brick and timber and still standing after many restorations. Timbuktu later grew into the leading centre of learning in West Africa.'],
        { wiki: { zh: '津加里贝尔清真寺', en: 'Djinguereber Mosque' } }),
      w(1326, -8.38, 11.38,
        ['尼亚尼（今几内亚东北部）', '返回都城，倡导伊斯兰学术', '穆萨回到都城后，命萨希利建造了一座带圆顶、抹灰泥并饰以彩色图案的觐见殿。他在各地修建聚礼清真寺，派学生到非斯留学，使伊斯兰学术在马里宫廷和城镇中扎下根基。马里此时的疆域西起大西洋，东至加奥。'],
        ['Niani (north-eastern Guinea)', 'Returns to his capital and promotes Islamic learning', 'Back in his capital, Musa had al-Sahili build a domed audience hall, plastered and decorated with coloured patterns. He founded Friday mosques, sent students to study in Fez and gave Islamic scholarship a firm footing at court and in the towns. Mali at this time stretched from the Atlantic to Gao.']),
      w(1337, -8.38, 11.38,
        ['尼亚尼（今几内亚东北部）', '约1337年去世', '1337年摩洛哥马林王朝攻占特莱姆森后，穆萨曾遣使祝贺，他大约就在此后不久去世（一说1332年），由儿子马加继位。1375年在马略卡绘制的《加泰罗尼亚地图集》把他画成手持金块的君主，可见其声名已远播欧洲。'],
        ['Niani (north-eastern Guinea)', 'Dies around 1337', 'Musa sent an embassy to congratulate the Marinid sultan of Morocco on taking Tlemcen in 1337 and probably died soon afterwards, though 1332 is also proposed. His son Magha succeeded him. The Catalan Atlas, drawn in Majorca in 1375, shows him as a crowned king holding a nugget of gold, a sign of how far his fame had spread.'],
        { wiki: { zh: '加泰罗尼亚地图集', en: 'Catalan Atlas' } }),
    ],
    wiki: { zh: '曼萨·穆萨', en: 'Mansa Musa' },
  },
  {
    id: 'ibn-battuta',
    name: { zh: '伊本·白图泰', en: 'Ibn Battuta' },
    birth: 1304, death: 1369, approx: true,
    title: { zh: '旅行家', en: 'Traveller and jurist' },
    region: 'africa', sprite: 'camel',
    summary: {
      zh: '摩洛哥旅行家，柏柏尔人，生于丹吉尔的法官世家。1325年离家朝觐，此后近三十年间游历北非、西亚、东非、中亚、南亚、东南亚直至中国，晚年又到过安达卢斯和西非的马里，行程约十二万公里，是蒸汽时代以前行程最远的旅行家之一。他口述、伊本·朱扎伊笔录的《伊本·白图泰游记》是研究14世纪伊斯兰世界的重要史料，其中部分行程的年代和真实性尚有争议（卒年为1368或1369年）。',
      en: 'Moroccan traveller, a Berber born into a family of legal scholars in Tangier. He left home in 1325 to make the pilgrimage to Mecca and for almost thirty years kept travelling: across North Africa, the Middle East, the East African coast, the Golden Horde, Central Asia, India, the Maldives, South-East Asia and China, and later to al-Andalus and Mali. The total, around 120,000 kilometres, makes him one of the most widely travelled people before the age of steam. His narrative, the Rihla, dictated to Ibn Juzayy, is a major source for the fourteenth-century Islamic world, though the dating and authenticity of some sections are disputed. He died in 1368 or 1369.',
    },
    route: [
      w(1304, -5.8, 35.77,
        ['丹吉尔（今摩洛哥丹吉尔）', '生于摩洛哥丹吉尔', '伊本·白图泰生于马林王朝治下的丹吉尔，家族世代研习伊斯兰教法。1325年6月，二十一岁的他独自离家，打算去麦加朝觐，途中在突尼斯加入朝觐驼队。他后来回忆说，离别双亲时心情沉重，“如同鸟儿离巢”。'],
        ['Tangier (now Tangier, Morocco)', 'Born in Tangier, Morocco', 'Ibn Battuta was born in Tangier under the Marinid dynasty, into a family of scholars of Islamic law. In June 1325, aged twenty-one, he set out alone to make the pilgrimage to Mecca and joined a pilgrim caravan at Tunis. He later recalled the sorrow of leaving his parents, departing "as birds forsake their nests".']),
      w(1326, 31.24, 30.04,
        ['开罗', '朝觐途中游历埃及', '他经亚历山大抵达马穆鲁克王朝的都城开罗，称它是“众城之母”，人口多得如海浪翻涌。他原想溯尼罗河而上、从红海港口艾达布渡海去麦加，却因当地战乱无船可渡，只好折回开罗，改道叙利亚。'],
        ['Cairo', 'Tours Egypt on the way to Mecca', 'By way of Alexandria he reached Cairo, the Mamluk capital, which he called the "mother of cities", its crowds surging like the waves of the sea. He travelled up the Nile meaning to cross the Red Sea from the port of Aydhab, but a local war had stopped the ships, so he returned to Cairo and took the road to Syria.']),
      w(1326, 36.29, 33.51,
        ['大马士革', '随朝觐商队南下', '他途经加沙、希伯伦、耶路撒冷等地来到大马士革，正值斋月，便留下来在倭马亚大清真寺听学者讲授圣训，并取得授课凭证。9月初，他随叙利亚的朝觐驼队出发，南下前往麦地那和麦加。'],
        ['Damascus', 'Joins the pilgrim caravan south', 'Passing through Gaza, Hebron and Jerusalem, he reached Damascus during Ramadan and stayed to hear scholars teach hadith at the Umayyad Mosque, collecting certificates of study. At the start of September he left with the Syrian pilgrim caravan for Medina and Mecca.'],
        { wiki: { zh: '倭马亚大清真寺', en: 'Umayyad Mosque' } }),
      w(1326, 39.83, 21.42,
        ['麦加', '完成首次朝觐', '驼队先到麦地那拜谒先知陵墓，随后抵达麦加。伊本·白图泰完成了朝觐的各项仪式，对当地居民的虔诚和慷慨印象深刻。他没有就此返乡，而是决定继续旅行，随伊拉克的朝觐驼队穿越阿拉伯半岛北上。'],
        ['Mecca', 'Completes his first hajj', 'The caravan stopped at Medina to visit the Prophet\'s tomb and then went on to Mecca, where Ibn Battuta performed the rites of the hajj and was struck by the piety and generosity of the townspeople. Instead of going home he resolved to keep travelling and joined the Iraqi caravan returning north across Arabia.'],
        { wiki: { zh: '禁寺', en: 'Masjid al-Haram' } }),
      w(1327, 44.36, 33.31,
        ['巴格达', '游历伊拉克与波斯', '他离开驼队，先游历纳杰夫、巴士拉、伊斯法罕和设拉子，再到巴格达。这座昔日的阿拔斯王朝都城自1258年被蒙古人攻陷后大半仍是废墟。他在此见到伊儿汗不赛因，并随其行营到过大不里士，此后返回麦加，在那里旅居求学。'],
        ['Baghdad', 'Travels through Iraq and Persia', 'Leaving the caravan, he visited Najaf, Basra, Isfahan and Shiraz before reaching Baghdad, the old Abbasid capital, much of it still in ruins since the Mongol sack of 1258. There he saw the Ilkhan Abu Said and travelled with the royal camp as far as Tabriz. He then went back to Mecca, where he stayed to study.']),
      w(1331, 45.34, 2.05,
        ['摩加迪沙（今索马里摩加迪沙）', '沿东非海岸南下', '他从吉达乘船沿红海南下，经也门的宰比德、塔伊兹和亚丁，渡海到非洲之角，再沿岸航行至摩加迪沙。他记述这是一座“极大的城市”，商人富有，出产的精美织物远销埃及，苏丹以丰盛的饭食款待来客。'],
        ['Mogadishu (now Mogadishu, Somalia)', 'Sails down the East African coast', 'From Jeddah he sailed down the Red Sea, visited Zabid, Taiz and Aden in Yemen, crossed to the Horn of Africa and coasted south to Mogadishu. He describes an "exceedingly large" town of wealthy merchants whose fine cloth was exported as far as Egypt, and a sultan who entertained visitors generously.'],
        { sea: true, via: [[40.5, 18.0], [43.5, 12.7], [51.0, 11.5]] }),
      w(1331, 39.51, -8.96,
        ['基尔瓦（今坦桑尼亚基尔瓦基西瓦尼）', '抵达斯瓦希里城邦基尔瓦', '他经蒙巴萨继续南行，到达其东非之行的最南端基尔瓦。这座岛上城邦靠转运内陆的黄金而富庶，他称它是最美丽、建造最精良的城市之一，并称赞苏丹哈桑谦逊好施。季风转向后，他乘船北返阿拉伯半岛。'],
        ['Kilwa (now Kilwa Kisiwani, Tanzania)', 'Reaches the Swahili city-state of Kilwa', 'Continuing south past Mombasa he reached Kilwa, the furthest point of his East African journey. The island town had grown rich on gold from the interior; he calls it one of the finest and best-built of cities and praises the humility and charity of its sultan, al-Hasan. When the monsoon turned he sailed back to Arabia.'],
        { sea: true, via: [[41.0, -2.5]], wiki: { zh: '基尔瓦基西瓦尼', en: 'Kilwa Kisiwani' } }),
      w(1332, 56.27, 27.1,
        ['霍尔木兹（今伊朗霍尔木兹岛）', '经阿曼至霍尔木兹', '他在阿拉伯半岛南岸的佐法尔登陆，再沿阿曼海岸航行，进入波斯湾口。当时的“新霍尔木兹”建在一座缺水的盐岛上，却是印度与信德货物的集散地。此后他横穿阿拉伯半岛，再次到麦加朝觐。'],
        ['Hormuz (now Hormuz Island, Iran)', 'Sails by Oman to Hormuz', 'He landed at Dhofar on the south coast of Arabia, then followed the coast of Oman to the mouth of the Persian Gulf. New Hormuz stood on a waterless island of salt but served as the market for the goods of India and Sind. From the Gulf he crossed Arabia to make the pilgrimage again.'],
        { sea: true, via: [[40.3, -8.5], [41.5, -3.5], [46.5, 2.0], [51.5, 8.0], [52.5, 11.8], [57.0, 17.0], [59.6, 20.0], [60.3, 22.4], [59.0, 24.5], [56.9, 26.0]] }),
      w(1332, 35.15, 42.03,
        ['锡诺普（今土耳其锡诺普）', '横穿安纳托利亚至黑海', '他从叙利亚乘热那亚商船到安纳托利亚南岸，一路受到各城“阿希”兄弟会的款待，见过奥斯曼君主奥尔汗，最后到达黑海港口锡诺普。游记中这一段行程的年代前后矛盾，此后数站的年份均为约数。'],
        ['Sinope (now Sinop, Turkey)', 'Crosses Anatolia to the Black Sea', 'A Genoese ship carried him from Syria to the south coast of Anatolia, where he was lodged from town to town by the akhi brotherhoods and met the Ottoman ruler Orhan, before reaching the Black Sea port of Sinope. The chronology of this part of his narrative is inconsistent, and the dates of the next few stages are approximate.']),
      w(1333, 35.38, 45.03,
        ['卡法（今克里米亚费奥多西亚）', '渡黑海至克里米亚', '他在锡诺普停留四十余日后渡海，途中遇上风暴，最后在克里米亚登岸，来到热那亚人的殖民城市卡法。这是他第一次置身基督徒的城市，四面响起的教堂钟声令他大为惊恐。此后他雇了马车进入钦察草原。'],
        ['Kaffa (now Feodosia, Crimea)', 'Crosses the Black Sea to Crimea', 'After some forty days at Sinope and a stormy crossing he landed in Crimea and came to Kaffa, a Genoese colony. It was the first Christian town he had stayed in, and the sound of church bells ringing on every side alarmed him. From there he hired wagons and set out across the Kipchak steppe.'],
        { sea: true }),
      w(1333, 47.17, 47.17,
        ['萨莱（金帐汗国都城，今俄罗斯阿斯特拉罕州）', '谒见金帐汗月即别', '他在北高加索的别什套山附近追上月即别汗（乌兹别克汗）的行营，对这座由毡帐、清真寺和集市组成的“移动城市”惊叹不已，又随行营到伏尔加河畔的阿斯特拉罕和都城萨莱。他称月即别是当时世界上最强大的七位君主之一。'],
        ['Sarai (capital of the Golden Horde, now Astrakhan Oblast, Russia)', 'Visits Ozbeg, khan of the Golden Horde', 'Near Mount Beshtau in the northern Caucasus he caught up with the travelling camp of Ozbeg Khan, a moving city of tents, mosques and markets that astonished him, and followed it to Astrakhan on the Volga and the capital, Sarai. He counted Ozbeg among the seven greatest rulers of the world.'],
        { via: [[34.9, 46.3], [36.8, 47.3], [39.4, 47.2], [43.05, 44.05], [48.0, 46.35]] }),
      w(1333, 28.98, 41.01,
        ['君士坦丁堡（今土耳其伊斯坦布尔）', '随拜占庭公主到访君士坦丁堡', '月即别的一位妻子是拜占庭皇帝的女儿，获准回娘家分娩，伊本·白图泰请求随行。他在君士坦丁堡停留了约一个月，受到皇帝安德洛尼卡三世接见，参观了圣索菲亚大教堂的外部。这是他到过的第一座伊斯兰世界之外的大都会。'],
        ['Constantinople (now Istanbul, Turkey)', 'Accompanies a Byzantine princess to Constantinople', 'One of Ozbeg\'s wives, a daughter of the Byzantine emperor, was allowed to return home to give birth, and Ibn Battuta asked to go with her escort. He spent about a month in Constantinople, was received by Emperor Andronikos III and saw Hagia Sophia from outside, his first great city beyond the lands of Islam.'],
        { via: [[39.7, 47.2], [34.0, 47.3], [30.5, 46.8], [28.4, 44.6], [27.3, 42.7], [27.8, 41.5]], wiki: { zh: '圣索菲亚大教堂', en: 'Hagia Sophia' } }),
      w(1333, 66.96, 39.65,
        ['撒马尔罕（今乌兹别克斯坦撒马尔罕）', '经花剌子模、布哈拉至撒马尔罕', '他返回萨莱，乘骆驼车穿过荒漠到花剌子模的玉龙杰赤，再经布哈拉来到撒马尔罕。蒙古西征已过去一个世纪，他看到布哈拉和巴尔赫仍多是废墟。途中他在察合台汗答儿麻失里的营地住了近两个月。'],
        ['Samarkand (now Samarkand, Uzbekistan)', 'Travels by Khwarazm and Bukhara to Samarkand', 'Returning to Sarai, he crossed the desert by camel-drawn wagon to Urgench in Khwarazm and went on through Bukhara to Samarkand. A century after the Mongol invasion he found Bukhara and Balkh still largely in ruins. On the way he spent nearly two months in the camp of Tarmashirin, khan of the Chagatai.'],
        { via: [[27.8, 41.5], [27.3, 42.7], [28.4, 44.6], [30.5, 46.8], [34.0, 47.3], [39.7, 47.2], [47.17, 47.17], [54.0, 47.2], [59.15, 42.3], [64.42, 39.77]] }),
      w(1334, 77.21, 28.61,
        ['德里', '经中亚抵达德里，任法官八年', '他翻越兴都库什山，1333年9月到达印度河，次年抵德里。苏丹穆罕默德·本·图格鲁克出手豪阔又喜怒无常，任命他为马立克派法官，俸禄优厚。他在此任职约八年，一度因与一位失宠的苏菲长老来往而险些丧命。'],
        ['Delhi', 'Reaches Delhi and serves eight years as a judge', 'He crossed the Hindu Kush, reached the Indus in September 1333 and arrived in Delhi the following year. Sultan Muhammad bin Tughluq, lavish and unpredictable, appointed him a Maliki judge on a generous salary. He held the post for about eight years and at one point came close to execution for his ties to a Sufi sheikh who had fallen from favour.'],
        { via: [[66.9, 36.76], [69.2, 34.5], [71.5, 30.2]], wiki: { zh: '顾特卜塔', en: 'Qutb Minar' } }),
      w(1342, 72.62, 22.31,
        ['坎贝（今印度古吉拉特邦肯帕德）', '奉命出使中国，自坎贝登船', '元顺帝遣使到德里，苏丹便派伊本·白图泰率使团携礼物回访。他从坎贝一带登船南下，在卡利卡特换乘中国帆船时遇上风暴，载着礼物和同伴的大船在港外沉没，他因留在岸上礼拜而幸免，却不敢再回德里。'],
        ['Cambay (now Khambhat, Gujarat, India)', 'Sent as envoy to China, he embarks near Cambay', 'When an embassy from the Yuan emperor reached Delhi, the sultan sent Ibn Battuta to lead a return mission with gifts. He took ship near Cambay and sailed south to Calicut to transfer to Chinese junks. A storm sank the great ship carrying the presents and his companions while he was ashore at prayer, and he dared not return to Delhi.']),
      w(1343, 73.5, 4.17,
        ['马尔代夫（马累）', '在马尔代夫任法官', '他来到马尔代夫群岛，被挽留担任法官，并与王室联姻。他试图严格推行教法，例如要求妇女遮蔽上身，却收效甚微；后来又卷入政争，只得离开。他对岛上的椰子、海贝和干鱼贸易有细致的记述。'],
        ['Maldives (Male)', 'Serves as a judge in the Maldives', 'In the Maldive Islands he was pressed to stay as chief judge and married into the ruling family. His attempts to enforce the law strictly, for instance by requiring women to cover the upper body, had little effect, and after becoming entangled in court politics he left. He describes in detail the trade in coconuts, cowrie shells and dried fish.'],
        { sea: true, via: [[72.0, 15.0], [74.0, 8.0]] }),
      w(1344, 80.5, 6.81,
        ['亚当峰（今斯里兰卡中部）', '登锡兰亚当峰', '他从马尔代夫渡海到锡兰，获当地国王准许并派人护送，攀登岛上的圣山亚当峰。山顶岩石上有一处巨大的“足印”，穆斯林视为人类始祖阿丹的足迹，佛教徒和印度教徒也各有说法。此后他转赴印度东南海岸和孟加拉。'],
        ['Adam\'s Peak (central Sri Lanka)', 'Climbs Adam\'s Peak in Ceylon', 'Crossing from the Maldives to Ceylon, he obtained a local king\'s leave and an escort to climb the holy mountain known as Adam\'s Peak. A large hollow in the summit rock is revered by Muslims as the footprint of Adam, and by Buddhists and Hindus under other names. He then went on to south-east India and Bengal.'],
        { sea: true, wiki: { zh: '亚当峰', en: 'Adam\'s Peak' } }),
      w(1345, 118.58, 24.87,
        ['刺桐（今福建泉州）', '从海路抵达元朝刺桐', '他经孟加拉、苏门答腊，乘帆船抵达刺桐，称它是世界上最大的港口之一，港内停泊着上百艘大船。他赞叹中国的瓷器、丝绸、纸币和旅途的安全，又记述到过广州和杭州；所谓北上汗八里的行程，学者多认为并不可信。'],
        ['Zaytun (now Quanzhou, Fujian)', 'Arrives by sea at Zaytun in Yuan China', 'Sailing by way of Bengal and Sumatra, he landed at Zaytun, which he calls one of the largest harbours in the world, with about a hundred great junks at anchor. He admired Chinese porcelain, silk, paper money and the safety of the roads, and describes Guangzhou and Hangzhou. His claimed journey north to Khanbaliq is widely doubted.'],
        { sea: true, via: [[80.5, 6.0], [92.0, 6.0], [100.0, 4.0], [104.5, 1.4], [109.0, 10.0], [114.0, 19.0]], wiki: { zh: '清净寺', en: 'Qingjing Mosque' } }),
      w(1347, 54.09, 17.02,
        ['佐法尔（今阿曼塞拉莱）', '自中国西归，抵达阿拉伯半岛', '他在刺桐搭上回航的帆船，经苏门答腊回到印度的奎隆和卡利卡特，放弃了重返德里的念头，1347年春渡过阿拉伯海，在佐法尔登岸。此后他经霍尔木兹、设拉子、巴格达一路向西。'],
        ['Dhofar (now Salalah, Oman)', 'Returns west from China to Arabia', 'At Zaytun he found a junk bound for home waters and sailed by Sumatra back to Quilon and Calicut in India. Giving up the idea of returning to Delhi, he crossed the Arabian Sea in spring 1347 and landed at Dhofar, then travelled west by Hormuz, Shiraz and Baghdad.'],
        { sea: true, via: [[114.0, 19.0], [109.0, 10.0], [104.5, 1.4], [100.0, 4.0], [92.0, 6.0], [80.5, 5.6], [76.0, 7.6], [65.0, 13.0]] }),
      w(1348, 36.29, 33.51,
        ['大马士革', '重返叙利亚，目睹黑死病', '回到大马士革，他才得知父亲已在十五年前去世。此时黑死病正席卷叙利亚和埃及，他记述大马士革每天有两千多人死亡，全城居民不分宗教一同出城祈祷。他随后经开罗去麦加作最后一次朝觐，再启程返乡。'],
        ['Damascus', 'Back in Syria, he witnesses the Black Death', 'In Damascus he learned that his father had died fifteen years earlier. The Black Death was then sweeping Syria and Egypt; he reports more than two thousand deaths a day in the city and describes its people of every faith going out together to pray. He went on through Cairo to make a final pilgrimage and then turned for home.'],
        { via: [[56.27, 27.1], [52.54, 29.6], [47.8, 30.5], [44.36, 33.31]] }),
      w(1349, -5.0, 34.03,
        ['非斯（今摩洛哥非斯）', '返回摩洛哥', '他从埃及经突尼斯乘船，途中在撒丁岛停靠，1349年11月抵达马林王朝的都城非斯，觐见苏丹阿布·伊南。离家二十四年后回到丹吉尔，他才知道母亲已在几个月前死于瘟疫。'],
        ['Fez (now Fez, Morocco)', 'Returns to Morocco', 'Travelling from Egypt by Tunis and then by ship, with a call at Sardinia, he reached Fez, the Marinid capital, in November 1349 and was received by Sultan Abu Inan. When he went on to Tangier after twenty-four years away, he found that his mother had died of the plague a few months before.']),
      w(1350, -3.6, 37.18,
        ['格拉纳达（今西班牙格拉纳达）', '游历安达卢斯', '他渡过海峡，先到直布罗陀参与防备卡斯蒂利亚人的进攻，随后游历龙达、马拉加，到达奈斯尔王朝的都城格拉纳达。在这里他结识了年轻的文人伊本·朱扎伊，后者日后成为他的游记的笔录者。'],
        ['Granada (now Granada, Spain)', 'Tours al-Andalus', 'He crossed the strait to Gibraltar, where he joined those preparing its defence against Castile, then travelled by Ronda and Malaga to Granada, capital of the Nasrid kingdom. There he met the young man of letters Ibn Juzayy, who would later write down his travels.'],
        { wiki: { zh: '阿尔罕布拉宫', en: 'Alhambra' } }),
      w(1353, -3.0, 16.77,
        ['廷巴克图（今马里通布图）', '穿越撒哈拉访问马里帝国', '1352年他从西吉尔马萨随驼队南行，经塔加扎盐矿和瓦拉塔，在马里都城住了约八个月，觐见曼萨·苏莱曼。1353年他顺尼日尔河到廷巴克图和加奥，在塔凯达接到苏丹召他回国的命令，遂随一支贩运奴隶的驼队北返。'],
        ['Timbuktu (now Tombouctou, Mali)', 'Crosses the Sahara to visit the Mali Empire', 'In 1352 he went south from Sijilmasa with a caravan by the salt mines of Taghaza and Walata, and spent about eight months at the capital of Mali, where he was received by Mansa Sulayman. In 1353 he followed the Niger to Timbuktu and Gao. At Takedda the sultan\'s order to return reached him, and he went north with a slave caravan.'],
        { wiki: { zh: '廷巴克图', en: 'Timbuktu' } }),
      w(1354, -5.0, 34.03,
        ['非斯（今摩洛哥非斯）', '奉苏丹之命口述游记', '回到非斯后，苏丹阿布·伊南命他把见闻口述下来，由伊本·朱扎伊整理润色，1355年底成书，原名意为“献给观览城市奇观与旅行异事者的珍品”，通称《游记》。书中个别段落借用了前人的著作。'],
        ['Fez (now Fez, Morocco)', 'Dictates his travels at the sultan\'s command', 'Back in Fez, Sultan Abu Inan ordered him to dictate what he had seen. Ibn Juzayy edited and polished the text, finished at the end of 1355 under a title meaning "A Gift to Those Who Contemplate the Wonders of Cities and the Marvels of Travelling", usually called the Rihla. Some passages borrow from earlier writers.']),
      w(1369, -5.8, 35.77,
        ['丹吉尔（相传的墓地所在，卒地不详）', '在摩洛哥去世', '游记完成后，伊本·白图泰的事迹很少见于记载，只知他在摩洛哥的某个城镇担任法官，于1368或1369年去世。丹吉尔老城中有一座相传是他的陵墓，但并无确证。他的游记直到19世纪才被译介到欧洲。'],
        ['Tangier (traditional site of his tomb; place of death unknown)', 'Dies in Morocco', 'Little is recorded of Ibn Battuta after the Rihla was finished, beyond the fact that he served as a judge in a Moroccan town and died in 1368 or 1369. A tomb in the old city of Tangier is traditionally said to be his, without firm evidence. His book became known in Europe only in the nineteenth century.']),
    ],
    wiki: { zh: '伊本·白图泰', en: 'Ibn Battuta' },
  },
  {
    id: 'zhu-yuanzhang',
    name: { zh: '朱元璋', en: 'Hongwu Emperor' },
    birth: 1328, death: 1398,
    title: { zh: '明朝开国皇帝', en: 'Founding emperor of the Ming dynasty' },
    region: 'china', lineage: 'china', sprite: 'seal',
    summary: {
      zh: '明朝开国皇帝，年号洪武，庙号太祖。出身贫苦，早年当过僧人，后投身元末红巾军起义，以应天（今南京）为根据地，先后击败陈友谅、张士诚等群雄，1368年称帝，同年攻占大都，结束元朝在中原的统治。在位期间废除丞相制度、强化皇权，严惩贪腐并屡兴大狱，同时丈量土地、编制户籍，恢复农业生产。',
      en: 'Founding emperor of the Ming dynasty, born Zhu Yuanzhang and known by his reign title Hongwu. Born into a destitute farming family and for a time a Buddhist novice, he joined the Red Turban rebellion against the Yuan, made Yingtian (Nanjing) his base and defeated rival warlords such as Chen Youliang and Zhang Shicheng. He proclaimed the Ming in 1368, and his armies took Dadu the same year, ending Mongol rule in China proper. As emperor he abolished the chancellorship and concentrated power in the throne, punished corruption harshly and carried out sweeping purges, while registering land and households and restoring agriculture.',
    },
    route: [
      w(1328, 117.56, 32.87,
        ['钟离（今安徽凤阳）', '生于濠州钟离贫苦农家', '朱元璋原名朱重八，生于濠州钟离县的一户佃农家庭，是家中最小的孩子。朱家祖籍句容，几代人为逃避赋役辗转迁徙。他幼年为地主放牛，只断断续续读过几个月私塾。'],
        ['Zhongli (now Fengyang, Anhui)', 'Born to poor farmers in Zhongli, Haozhou', 'Zhu Yuanzhang, originally named Zhu Chongba, was the youngest child of a tenant-farming family in Zhongli county. The family had moved from place to place for generations to escape taxes and labour service. As a boy he herded cattle for a landlord and had only a few months of schooling.']),
      w(1344, 117.56, 32.87,
        ['皇觉寺（今安徽凤阳）', '父母兄长死于灾荒瘟疫，入寺为僧', '淮河流域大旱，又遭蝗灾和瘟疫，半个月内父亲、母亲和长兄相继去世，家里连买棺材和坟地的钱都没有，靠邻人施舍一块地才得安葬。十六岁的朱元璋走投无路，到附近的皇觉寺当了小行童。'],
        ['Huangjue Temple (now Fengyang, Anhui)', 'Orphaned by famine and plague, he enters a monastery', 'Drought, locusts and epidemic struck the Huai valley, and within a fortnight his father, mother and eldest brother died. Too poor to buy coffins or a burial plot, the family depended on a neighbour for a grave. With nowhere to turn, the sixteen-year-old became a novice at the nearby Huangjue Temple.']),
      w(1345, 115.68, 32.18,
        ['光州、固始一带（今河南东南部）', '托钵云游淮西三年', '入寺不到两个月，寺里也断了粮，僧人们被打发外出化缘。朱元璋南到合肥，西至光州、固始、信阳，北抵汝州、陈州，在淮西流浪了三年。这段经历让他熟悉了各地的山川形势，也见识了民间的疾苦。'],
        ['Guangzhou and Gushi area (now south-eastern Henan)', 'Wanders the Huai region as a begging monk', 'Within two months the temple ran out of grain and sent its monks out to beg. Zhu Yuanzhang roamed for three years, south to Hefei, west to Guangzhou, Gushi and Xinyang and north to Ruzhou and Chenzhou. He came to know the lie of the land and saw at first hand how ordinary people were suffering.']),
      w(1352, 117.56, 32.87,
        ['濠州（今安徽凤阳）', '投奔郭子兴红巾军', '红巾军起事遍及江淮，皇觉寺毁于兵火。二十出头的朱元璋接到儿时伙伴汤和的来信，又经占卜，决定到濠州城投奔郭子兴。他作战勇敢、处事有谋，很快升为亲兵九夫长，并娶了郭子兴的养女马氏。'],
        ['Haozhou (now Fengyang, Anhui)', 'Joins the Red Turban army of Guo Zixing', 'As Red Turban risings spread across the region and Huangjue Temple was burned, Zhu Yuanzhang, in his early twenties, received a letter from his boyhood friend Tang He, cast lots and went to Haozhou to join Guo Zixing. Brave and shrewd, he was soon a guard commander and married Guo\'s foster daughter, the future Empress Ma.']),
      w(1354, 118.31, 32.3,
        ['滁州（今安徽滁州）', '南略定远，攻占滁州', '朱元璋不愿卷入濠州诸帅的内斗，带着徐达等二十四名同乡南下定远，收编了几支地方武装，兵力增至两万余人，随后攻下滁州。定远人李善长前来投奔，劝他效法同是布衣出身的汉高祖刘邦。'],
        ['Chuzhou (now Chuzhou, Anhui)', 'Strikes out on his own and takes Chuzhou', 'Unwilling to be drawn into the quarrels of the Haozhou commanders, Zhu went south to Dingyuan with twenty-four men from his home district, among them Xu Da. He absorbed several local forces, raising his strength to over twenty thousand, and took Chuzhou. Li Shanchang joined him and urged him to model himself on the commoner emperor Liu Bang.']),
      w(1355, 118.46, 31.65,
        ['采石矶、太平（今安徽马鞍山）', '渡江攻取太平', '郭子兴病逝后，朱元璋成为这支军队的实际统帅。和州缺粮，他借助巢湖水师的船只，从采石矶强渡长江，常遇春率先登岸。攻下太平后他严禁抢掠，当地儒士陶安等人出城迎接。'],
        ['Caishi and Taiping (now Ma\'anshan, Anhui)', 'Crosses the Yangtze and takes Taiping', 'After Guo Zixing died, Zhu became the effective commander of his army. Short of grain at Hezhou, he used the boats of the Chao Lake fleet to force a crossing of the Yangtze at Caishi, where Chang Yuchun was first ashore. He took Taiping, forbade looting and was welcomed by local scholars such as Tao An.']),
      w(1356, 118.78, 32.06,
        ['集庆（今江苏南京）', '攻占集庆，改名应天府', '朱元璋第三次进攻集庆路终于破城，把它改名为应天府，作为根据地。此后他采纳老儒朱升“高筑墙，广积粮，缓称王”的建议，名义上仍奉小明王韩林儿的龙凤年号，埋头经营江南。'],
        ['Jiqing (now Nanjing, Jiangsu)', 'Captures Jiqing and renames it Yingtian', 'On his third attempt Zhu Yuanzhang took Jiqing and renamed it Yingtian, making it his base. He followed the advice of the scholar Zhu Sheng to "build high walls, store grain and delay claiming a throne", continuing to acknowledge the Red Turban emperor Han Lin\'er while he consolidated the lower Yangtze.'],
        { wiki: { zh: '南京城墙', en: 'City Wall of Nanjing' } }),
      w(1358, 119.65, 29.08,
        ['婺州（今浙江金华）', '亲征浙东，延揽儒士', '朱元璋亲率大军攻克婺州，在此设中书分省，开办郡学，聘请当地学者讲授经史。浙东素称文献之邦，宋濂、刘基、章溢、叶琛“四先生”随后应聘到应天，成为他最重要的谋士。'],
        ['Wuzhou (now Jinhua, Zhejiang)', 'Campaigns in eastern Zhejiang and recruits scholars', 'Zhu led his army in person to take Wuzhou, where he set up a branch secretariat, opened a prefectural school and engaged local scholars to lecture on the classics. Soon afterwards the "four masters" of eastern Zhejiang, Song Lian, Liu Ji, Zhang Yi and Ye Chen, came to Yingtian and became his chief advisers.']),
      w(1360, 118.73, 32.1,
        ['龙湾（今南京下关一带）', '龙湾之战击退陈友谅', '占据长江中游的陈友谅攻陷太平后自立为帝，率水师直扑应天。朱元璋采用刘基之策，让陈友谅的旧友康茂才写信诈降，诱敌深入，在龙湾设伏，乘退潮时发起攻击，缴获大批战船。'],
        ['Longwan (now Xiaguan, Nanjing)', 'Repels Chen Youliang at Longwan', 'Chen Youliang, master of the middle Yangtze, took Taiping, declared himself emperor and sailed against Yingtian. On Liu Ji\'s advice Zhu had Kang Maocai, an old acquaintance of Chen, send a false offer to defect, drew the fleet into an ambush at Longwan and attacked as the tide ebbed, capturing many ships.']),
      w(1363, 116.3, 29.1,
        ['鄱阳湖（今江西北部）', '鄱阳湖之战击败陈友谅', '陈友谅以巨舰围攻洪都（今南昌）八十五天不下，朱元璋率军来救，两军在鄱阳湖鏖战三十多天。朱军船小，借东北风用火攻焚毁敌方连锁的大船；陈友谅突围时中箭身亡。这是中国古代规模最大的水战之一。'],
        ['Poyang Lake (northern Jiangxi)', 'Defeats Chen Youliang on Poyang Lake', 'Chen Youliang besieged Hongdu (Nanchang) for eighty-five days with his towering warships until Zhu came to its relief, and the fleets fought on Poyang Lake for more than a month. Zhu\'s smaller boats used fire, carried by a north-east wind, against Chen\'s chained ships, and Chen was killed by an arrow while trying to break out.'],
        { wiki: { zh: '鄱阳湖之战', en: 'Battle of Lake Poyang' } }),
      w(1364, 114.3, 30.55,
        ['武昌（今湖北武汉）', '亲征武昌，平定陈汉', '朱元璋在应天称吴王，建百官，随后再次亲征武昌。陈友谅之子陈理出城投降，湖广、江西尽入版图。此后他转而对付东面占据苏州的张士诚，1367年攻克平江，基本统一了江南。'],
        ['Wuchang (now Wuhan, Hubei)', 'Takes Wuchang and ends the Chen Han regime', 'Zhu proclaimed himself Prince of Wu at Yingtian, appointed a full staff of officials and then led a second expedition to Wuchang, where Chen Youliang\'s son Chen Li surrendered. With Huguang and Jiangxi secured he turned on Zhang Shicheng in Suzhou, which fell in 1367, leaving him master of the south.']),
      w(1368, 118.78, 32.06,
        ['应天府（今江苏南京）', '称帝，国号大明', '1368年正月初四，朱元璋在应天南郊祭告天地，即皇帝位，国号大明，年号洪武，立马氏为皇后、朱标为太子。此前他已派徐达、常遇春率二十五万大军北伐，当年八月明军攻入大都，元顺帝北走上都。'],
        ['Yingtian (now Nanjing, Jiangsu)', 'Proclaims himself emperor of the Great Ming', 'On 23 January 1368 Zhu Yuanzhang sacrificed to Heaven and Earth south of Yingtian and took the throne as emperor of the Great Ming, with the reign title Hongwu. Lady Ma became empress and Zhu Biao heir. The northern expedition he had sent under Xu Da and Chang Yuchun entered Dadu that September, and the Yuan emperor fled north.'],
        { event: 'ming-founding' }),
      w(1368, 114.31, 34.8,
        ['汴梁（今河南开封）', '亲赴汴梁部署北伐', '北伐军攻下山东、河南后，朱元璋亲自来到汴梁，与徐达等将领商定直取大都的方略，叮嘱入城后不得杀掠。他一度打算在这座北宋故都建都，下诏以应天为南京、开封为北京，后来未再实行。'],
        ['Bianliang (now Kaifeng, Henan)', 'Goes to Kaifeng to direct the northern campaign', 'Once the expedition had taken Shandong and Henan, Zhu travelled to Bianliang to settle with Xu Da and his generals the plan for a direct advance on Dadu, insisting that the city be spared slaughter and looting. He considered making the old Song capital his own, naming Yingtian the southern and Kaifeng the northern capital, but the idea lapsed.']),
      w(1375, 117.55, 32.89,
        ['中都（今安徽凤阳）', '巡视中都，下令停建', '朱元璋自1369年起在家乡临濠大兴土木营建中都，征调了大批工匠、军士和民夫，其宫殿规制成为后来南京和北京宫城的蓝本。1375年他亲临视察后，以劳费过重为由下令停工，仍以南京为都城。'],
        ['Zhongdu (now Fengyang, Anhui)', 'Inspects his new "Central Capital" and halts the work', 'From 1369 Zhu had a grand Central Capital built at his birthplace, drafting large numbers of craftsmen, soldiers and labourers; its plan served as a model for the later palaces of Nanjing and Beijing. After visiting the site in 1375 he stopped construction on grounds of cost and kept Nanjing as his capital.']),
      w(1380, 118.78, 32.06,
        ['应天府（今江苏南京）', '诛胡惟庸，废除丞相', '朱元璋以谋反罪处死丞相胡惟庸，随即撤销中书省，由皇帝直接统领六部，在中国延续一千多年的宰相制度至此废除。此案与后来的蓝玉案前后株连数万人，开国功臣大多未能幸免。'],
        ['Yingtian (now Nanjing, Jiangsu)', 'Executes Hu Weiyong and abolishes the chancellorship', 'Zhu had his chancellor Hu Weiyong executed for treason, then abolished the Central Secretariat and placed the Six Ministries directly under the throne, ending an office that had existed for well over a thousand years. This case and the later purge of Lan Yu claimed tens of thousands of lives, including most of the founding generals.']),
      w(1398, 118.78, 32.06,
        ['应天府（今江苏南京）', '病逝，葬于孝陵', '太子朱标于1392年先他而死，朱元璋立孙子朱允炆为皇太孙。1398年6月他在南京病逝，在位三十一年，与马皇后合葬于钟山南麓的孝陵。一年后，燕王朱棣起兵“靖难”，最终夺取了侄子的皇位。'],
        ['Yingtian (now Nanjing, Jiangsu)', 'Dies and is buried at Xiaoling', 'His heir Zhu Biao died in 1392, and Zhu named his grandson Zhu Yunwen as successor. He died in Nanjing in June 1398 after a reign of thirty-one years and was buried beside Empress Ma at Xiaoling, below Zhongshan. A year later his son the Prince of Yan rose in arms and went on to seize the throne.'],
        { wiki: { zh: '明孝陵', en: 'Ming Xiaoling Mausoleum' } }),
    ],
    wiki: { zh: '朱元璋', en: 'Hongwu Emperor' },
  },
  {
    id: 'timur',
    name: { zh: '帖木儿', en: 'Timur' },
    birth: 1336, death: 1405,
    title: { zh: '帖木儿帝国创建者', en: 'Founder of the Timurid Empire' },
    region: 'central-asia', sprite: 'horse',
    summary: {
      zh: '帖木儿帝国的创建者，出身突厥化的蒙古巴鲁剌思部，因腿伤致残而有“跛子帖木儿”之称。他以撒马尔罕为都城，三十余年间征服中亚、波斯与两河流域，北击金帐汗国，南掠德里，西败马穆鲁克王朝和奥斯曼帝国，建立起庞大的帝国。他的征伐以大规模屠城著称，同时又把各地的工匠和学者集中到撒马尔罕，开启了帖木儿时期的文化艺术繁荣。1405年在东征明朝途中病逝。',
      en: 'Founder of the Timurid Empire, born into the Barlas, a Turkicised Mongol tribe, and known as Timur the Lame, or Tamerlane, from his crippling wounds. From his capital at Samarkand he spent more than three decades on campaign, conquering Central Asia, Persia and Mesopotamia, breaking the Golden Horde, sacking Delhi and defeating the Mamluks and the Ottomans. His wars were marked by massacres on a vast scale, yet he also gathered craftsmen and scholars in Samarkand, laying the ground for the Timurid flowering of art and architecture. He died in 1405 on the way to invade Ming China.',
    },
    route: [
      w(1336, 66.83, 39.05,
        ['渴石（今乌兹别克斯坦沙赫里萨布兹）', '生于察合台汗国渴石附近', '帖木儿生于渴石附近的一个村庄，父亲是突厥化蒙古部落巴鲁剌思部的小贵族。当时察合台汗国已经分裂，河中地区由各部首领割据。他并非成吉思汗的后裔，因此终生只称“埃米尔”，不称汗。'],
        ['Kesh (now Shahrisabz, Uzbekistan)', 'Born near Kesh in the Chagatai Khanate', 'Timur was born in a village near Kesh, the son of a minor noble of the Barlas, a Turkicised Mongol tribe. The Chagatai Khanate had by then broken up, and Transoxiana was divided among tribal chiefs. Not being a descendant of Genghis Khan, he never took the title of khan and ruled as amir.'],
        { wiki: { zh: '沙赫里萨布兹', en: 'Shahrisabz' } }),
      w(1363, 61.86, 30.96,
        ['锡斯坦（今伊朗、阿富汗交界一带）', '在锡斯坦负伤致残', '青年帖木儿在河中的部落混战中时而得势、时而流亡，一度带着少数随从充当雇佣兵。约1363年他在锡斯坦作战时右腿和右手中箭，落下终身残疾，波斯语称他为“跛子帖木儿”，欧洲语言中的“Tamerlane”即由此而来。'],
        ['Sistan (on the present Iran-Afghanistan border)', 'Crippled by wounds in Sistan', 'As a young man Timur rose and fell in the tribal wars of Transoxiana and for a time led a small band as a mercenary. Fighting in Sistan around 1363, he was hit by arrows in the right leg and right hand and left permanently lame. The Persian nickname Timur-i Lang, "Timur the Lame", became Tamerlane in European languages.']),
      w(1370, 66.9, 36.76,
        ['巴尔赫（今阿富汗巴尔赫）', '击败对手忽辛，自立为埃米尔', '帖木儿与妻兄、昔日的盟友忽辛反目，率军围攻其据点巴尔赫。忽辛投降后被杀，帖木儿迎娶他的遗孀、察合台汗之女，由此获得“古列干”（成吉思汗家族女婿）的称号，并被诸将拥立为河中之主。'],
        ['Balkh (now Balkh, Afghanistan)', 'Defeats his rival Husayn and becomes amir', 'Timur fell out with Amir Husayn, his brother-in-law and former ally, and besieged him in Balkh. Husayn surrendered and was killed. Timur married his widow, a daughter of a Chagatai khan, which gave him the title guregen, royal son-in-law, and the assembled commanders acknowledged him as ruler of Transoxiana.']),
      w(1370, 66.96, 39.65,
        ['撒马尔罕（今乌兹别克斯坦撒马尔罕）', '定都撒马尔罕', '帖木儿以撒马尔罕为都，重修城墙和内堡，并扶立一位成吉思汗后裔作名义上的汗。此后三十多年，他把历次征伐中俘获的工匠、学者和财富源源运回此城，使它成为中亚最繁华的都会。'],
        ['Samarkand (now Samarkand, Uzbekistan)', 'Makes Samarkand his capital', 'Timur made Samarkand his capital, rebuilt its walls and citadel and installed a descendant of Genghis Khan as nominal khan. Over the next three decades he sent back to it the craftsmen, scholars and treasure taken on his campaigns, turning it into the most splendid city of Central Asia.']),
      w(1379, 59.15, 42.3,
        ['玉龙杰赤（今土库曼斯坦库尼亚-乌尔根奇）', '征服花剌子模', '帖木儿多次出兵阿姆河下游的花剌子模，1379年经三个月围攻攻克其都城玉龙杰赤，把城中的工匠和学者迁往撒马尔罕。1388年当地再度反叛，他下令将全城夷为平地，这座丝路名城从此一蹶不振。'],
        ['Urgench (now Konye-Urgench, Turkmenistan)', 'Conquers Khwarazm', 'After several expeditions against Khwarazm on the lower Amu Darya, Timur took its capital Urgench in 1379 after a three-month siege and moved its craftsmen and scholars to Samarkand. When the region rebelled in 1388 he had the city razed, and the old Silk Road centre never recovered.'],
        { wiki: { zh: '库尼亚-乌尔根奇', en: 'Konye-Urgench' } }),
      w(1381, 62.2, 34.34,
        ['赫拉特（今阿富汗赫拉特）', '攻取赫拉特，进入呼罗珊', '伊儿汗国瓦解后，波斯各地小王朝林立。帖木儿首先进攻呼罗珊的库尔特王朝，其都城赫拉特开城投降，城门被拆下运往渴石。此后数年他逐一征服波斯东部，赫拉特后来成为帖木儿王朝的文化中心。'],
        ['Herat (now Herat, Afghanistan)', 'Takes Herat and enters Khorasan', 'Persia had split into small dynasties after the fall of the Ilkhanate. Timur first attacked the Kart rulers of Khorasan, whose capital Herat surrendered; its gates were carried off to Kesh. Over the following years he subdued eastern Persia piece by piece, and Herat later became the cultural centre of his dynasty.']),
      w(1386, 44.8, 41.7,
        ['第比利斯（今格鲁吉亚第比利斯）', '“三年战役”，兵入高加索', '帖木儿发动为期三年的西征，先取大不里士，随后北上高加索，攻陷第比利斯，俘虏格鲁吉亚国王巴格拉特五世。此后二十年间他多次入侵格鲁吉亚，这个基督教王国的城镇和修道院屡遭破坏。'],
        ['Tbilisi (now Tbilisi, Georgia)', 'Invades the Caucasus on the "Three-Year Campaign"', 'Timur set out on a three-year campaign to the west, took Tabriz and then marched into the Caucasus, where he stormed Tbilisi and captured King Bagrat V of Georgia. He invaded Georgia repeatedly over the next two decades, devastating the towns and monasteries of the Christian kingdom.']),
      w(1387, 51.67, 32.65,
        ['伊斯法罕（今伊朗伊斯法罕）', '征服波斯', '伊斯法罕起初开城归顺，但城中居民随后暴动，杀死了征收贡赋的帖木儿军士。他下令屠城报复，据其宫廷史家记载，城外用人头垒起了多座高塔，死者数以万计。设拉子等地闻讯纷纷投降。'],
        ['Isfahan (now Isfahan, Iran)', 'Conquers Persia', 'Isfahan at first submitted, but its people then rose and killed the soldiers sent to collect the ransom. Timur ordered a massacre in reprisal; his own court historians describe towers built of severed heads outside the walls and tens of thousands dead. Shiraz and other cities hastened to surrender.']),
      w(1391, 50.8, 54.0,
        ['孔杜尔恰河（今俄罗斯萨马拉州，位置为约略）', '北征钦察草原，击败脱脱迷失', '金帐汗脱脱迷失原是靠帖木儿扶持上台的，后来却屡次进犯其领地。帖木儿率大军北上，在草原上行军近四个月，终于在伏尔加河中游的孔杜尔恰河畔追上对手并将其击败，但脱脱迷失得以逃脱。'],
        ['Kondurcha River (now Samara Oblast, Russia; location approximate)', 'Marches across the steppe and defeats Tokhtamysh', 'Tokhtamysh, khan of the Golden Horde, owed his throne to Timur but had repeatedly raided his lands. Timur led a great army north across the steppe for nearly four months, brought his enemy to battle on the Kondurcha River near the middle Volga and defeated him, though Tokhtamysh escaped.']),
      w(1395, 45.0, 43.6,
        ['捷列克河（今俄罗斯北高加索）', '击败金帐汗脱脱迷失', '脱脱迷失卷土重来，两军在高加索北麓的捷列克河畔决战，帖木儿险些阵亡，最终获胜。他乘胜北上直抵梁赞公国边境的叶列茨，回师时焚毁萨莱和阿斯特拉罕，金帐汗国和草原丝路的贸易从此衰落。'],
        ['Terek River (North Caucasus, Russia)', 'Defeats Tokhtamysh of the Golden Horde', 'Tokhtamysh returned to the attack and the armies met on the Terek, north of the Caucasus, where Timur was nearly killed before winning the day. He pushed north as far as Yelets on the border of Ryazan and, on his way back, burned Sarai and Astrakhan, a blow from which the Golden Horde and its steppe trade never recovered.']),
      w(1398, 77.21, 28.61,
        ['德里', '攻陷德里', '帖木儿以德里苏丹国对异教徒过于宽容为由，翻越兴都库什山，渡过印度河南下。1398年12月他在德里城外击溃图格鲁克王朝的军队和战象，入城后纵兵洗劫数日，随后带着大批财物、工匠和大象返回。'],
        ['Delhi', 'Sacks Delhi', 'Claiming that the Delhi Sultanate was too tolerant of its non-Muslim subjects, Timur crossed the Hindu Kush and the Indus. In December 1398 he routed the Tughluq army and its war elephants outside Delhi. The city was plundered for several days, and he withdrew with vast booty, craftsmen and elephants.']),
      w(1399, 66.96, 39.65,
        ['撒马尔罕（今乌兹别克斯坦撒马尔罕）', '兴建比比哈努姆清真寺', '从印度返回后，帖木儿动用掳来的工匠，并用大象运送石料，在撒马尔罕兴建一座巨大的聚礼清真寺，后世以“比比哈努姆”相称。它是当时伊斯兰世界最大的清真寺之一，但因赶工过急，建成不久就开始损坏。'],
        ['Samarkand (now Samarkand, Uzbekistan)', 'Builds the Bibi-Khanym Mosque', 'Back from India, Timur set captured craftsmen to work, with elephants hauling stone, on a huge congregational mosque in Samarkand, later known as the Bibi-Khanym. It was among the largest mosques in the Islamic world, but it had been built in such haste that it began to crumble soon after completion.'],
        { wiki: { zh: '比比哈努姆清真寺', en: 'Bibi-Khanym Mosque' } }),
      w(1400, 37.16, 36.2,
        ['阿勒颇（今叙利亚阿勒颇）', '西征叙利亚，攻陷阿勒颇', '帖木儿开始“七年战役”，先洗劫小亚细亚东部的锡瓦斯，随后南下进攻埃及马穆鲁克王朝治下的叙利亚。1400年秋他在阿勒颇城外击溃守军，乘胜攻入城中，全城遭到数日屠掠。'],
        ['Aleppo (now Aleppo, Syria)', 'Invades Syria and takes Aleppo', 'Opening his "Seven-Year Campaign", Timur sacked Sivas in eastern Anatolia and then turned south into Syria, which belonged to the Mamluk sultans of Egypt. In autumn 1400 he broke the defending army outside Aleppo and entered the city on its heels; it was given over to several days of killing and plunder.']),
      w(1401, 36.29, 33.51,
        ['大马士革', '攻陷大马士革，会见伊本·赫勒敦', '马穆鲁克苏丹撤回埃及后，大马士革于1401年初投降，仍遭洗劫和焚烧，倭马亚大清真寺严重受损，工匠被迁往撒马尔罕。围城期间，史学家伊本·赫勒敦缒城而出，与帖木儿多次长谈，并在自传中留下了记录。'],
        ['Damascus', 'Takes Damascus and meets Ibn Khaldun', 'After the Mamluk sultan withdrew to Egypt, Damascus surrendered early in 1401 but was still sacked and burned; the Umayyad Mosque was badly damaged and the city\'s craftsmen were deported to Samarkand. During the siege the historian Ibn Khaldun was lowered from the walls and held several long conversations with Timur, which he recorded in his autobiography.']),
      w(1401, 44.36, 33.31,
        ['巴格达', '攻陷巴格达', '帖木儿曾在1393年占领巴格达，此后该城又被札剌亦儿王朝夺回。1401年夏他顶着酷暑围城四十天，破城后下令屠杀居民，据记载城外又垒起了上百座人头塔，除清真寺等宗教建筑外，城市大半被毁。'],
        ['Baghdad', 'Sacks Baghdad', 'Timur had occupied Baghdad in 1393, but the Jalayirid sultan later recovered it. In the summer of 1401 he besieged the city for forty days in fierce heat, and when it fell he ordered a general massacre; the chroniclers again speak of more than a hundred towers of heads. Apart from mosques and other religious buildings, much of the city was destroyed.']),
      w(1402, 32.86, 39.93,
        ['安卡拉（今土耳其安卡拉）', '安卡拉之战生擒巴耶济德一世', '1402年7月，帖木儿与奥斯曼苏丹“雷霆”巴耶济德一世在安卡拉东北的平原上决战。帖木儿事先截断水源，战斗中奥斯曼军的安纳托利亚部队又临阵倒戈，巴耶济德被俘，次年死于囚禁中。奥斯曼帝国由此陷入十余年的内乱。'],
        ['Ankara (now Ankara, Turkey)', 'Captures Sultan Bayezid I at the Battle of Ankara', 'In July 1402 Timur met the Ottoman sultan Bayezid I, "the Thunderbolt", on the plain north-east of Ankara. Timur had cut off the water supply, and Bayezid\'s Anatolian contingents went over to the enemy during the fighting. The sultan was captured and died in captivity the next year, and the Ottoman state fell into a decade of civil war.'],
        { wiki: { zh: '安卡拉之战', en: 'Battle of Ankara' } }),
      w(1402, 27.14, 38.42,
        ['士麦那（今土耳其伊兹密尔）', '攻克医院骑士团的士麦那', '帖木儿的军队横扫安纳托利亚西部，直抵爱琴海。1402年12月，他亲自指挥围攻由医院骑士团据守的士麦那港口城堡，填塞港口、挖掘地道，约两周后破城。这是他西征到达的最远处。'],
        ['Smyrna (now Izmir, Turkey)', 'Storms the Hospitaller stronghold of Smyrna', 'Timur\'s troops swept across western Anatolia to the Aegean. In December 1402 he personally directed the siege of the harbour fortress of Smyrna, held by the Knights Hospitaller, blocking the port and mining the walls until it fell after about two weeks. It was the westernmost point of his campaigns.']),
      w(1404, 66.96, 39.65,
        ['撒马尔罕（今乌兹别克斯坦撒马尔罕）', '回到撒马尔罕，筹划远征明朝', '帖木儿凯旋后在城外的花园中连日举行盛大的宴会，为孙子们完婚。卡斯蒂利亚国王的使节克拉维约此时到访，留下了详细的见闻录。他看到明朝的使臣也在场，而帖木儿故意把他们的座次排在西班牙人之后。'],
        ['Samarkand (now Samarkand, Uzbekistan)', 'Returns to Samarkand and plans to invade Ming China', 'Home in triumph, Timur held weeks of feasting in the gardens outside the city to celebrate the weddings of his grandsons. Ruy Gonzalez de Clavijo, ambassador of the king of Castile, was present and left a detailed account, noting that Timur pointedly seated the envoys of the Ming emperor below the Spaniards.']),
      w(1405, 68.3, 42.85,
        ['讹答剌（今哈萨克斯坦南部）', '东征途中病逝', '1404年底，年近七十的帖木儿不顾严寒，率大军从撒马尔罕出发东征明朝。行至锡尔河畔的讹答剌时他一病不起，于1405年2月去世，远征随之取消。遗体运回撒马尔罕，葬于古尔-艾米尔陵墓，诸子孙随即为争位而开战。'],
        ['Otrar (now in southern Kazakhstan)', 'Dies on the march against China', 'Late in 1404 Timur, close to seventy, set out from Samarkand in bitter cold to invade Ming China. He fell ill at Otrar on the Syr Darya and died in February 1405, and the expedition was abandoned. His body was taken back to Samarkand and laid in the Gur-e-Amir, while his sons and grandsons began fighting over the succession.'],
        { wiki: { zh: '古尔-艾米尔陵墓', en: 'Gur-e-Amir' } }),
    ],
    wiki: { zh: '帖木儿', en: 'Timur' },
  },
  {
    id: 'zheng-he',
    name: { zh: '郑和', en: 'Zheng He' },
    birth: 1371, death: 1433,
    title: { zh: '航海家、外交家', en: 'Admiral and diplomat' },
    region: 'china', lineage: 'china', sprite: 'ship',
    summary: {
      zh: '明代航海家、外交家，本姓马，云南昆阳人，回族。少年时被俘入宫，在燕王朱棣府中成长，因靖难之功获赐姓郑。1405年至1433年间，他奉明成祖与明宣宗之命七下西洋，率领当时世界上规模最大的船队，访问了东南亚、南亚、西亚和东非的三十多个国家和地区，最远到达红海和非洲东海岸，促进了中外经济文化交流。',
      en: 'Ming dynasty admiral and diplomat, born Ma He into a Hui Muslim family at Kunyang in Yunnan. Captured as a boy and made a eunuch, he grew up in the household of Zhu Di, Prince of Yan, who later, as the Yongle Emperor, gave him the surname Zheng. Between 1405 and 1433, on the orders of the Yongle and Xuande emperors, he led seven expeditions to the "Western Ocean" with the largest fleets the world had yet seen. They visited more than thirty countries and regions in South-East Asia, South Asia, West Asia and East Africa, reaching the Red Sea and the East African coast.',
    },
    route: [
      w(1371, 102.6, 24.67,
        ['昆阳（今云南昆明晋宁区）', '生于回族马姓家庭', '郑和本姓马，小名三保，生于滇池南岸昆阳州的一个回族家庭，先祖据传是元初治理云南的赛典赤·赡思丁。他的祖父和父亲都曾远赴麦加朝觐，被尊称为“哈只”，这或许让他自幼就听说过西洋的见闻。'],
        ['Kunyang (now Jinning District, Kunming, Yunnan)', 'Born into a Hui Muslim family named Ma', 'Zheng He was born Ma He, also called Sanbao, into a Hui family at Kunyang on the southern shore of Lake Dian; tradition traces the family to Sayyid Ajall, the Yuan governor of Yunnan. His grandfather and father had both made the pilgrimage to Mecca and bore the title hajji, so he may have heard of the western seas as a child.']),
      w(1381, 116.39, 39.91,
        ['北平（今北京）', '明军平定云南时被俘，后入燕王朱棣府中', '1381年底明军攻入云南，十岁左右的马和被俘并遭阉割，随军北上。约1385年前后，他被分派到北平的燕王朱棣府中服役。他身材魁梧、聪敏好学，逐渐成为燕王信任的近侍。'],
        ['Beiping (now Beijing)', 'Captured in Yunnan, he enters the Prince of Yan\'s household', 'When Ming armies invaded Yunnan at the end of 1381, Ma He, then about ten, was captured, castrated and taken north with the troops. Around 1385 he was assigned to the household of Zhu Di, Prince of Yan, at Beiping. Tall, able and studious, he became one of the prince\'s trusted attendants.']),
      w(1399, 116.55, 39.96,
        ['郑村坝（今北京朝阳区东坝）', '靖难之役中立功于郑村坝', '建文帝削藩，燕王朱棣起兵“靖难”。1399年冬，南军主帅李景隆率大军围攻北平，燕王回师在城东的郑村坝大破其军。马和在此役及此后的战事中屡立战功，据说“郑”姓即由此地而来。'],
        ['Zhengcunba (now Dongba, Chaoyang District, Beijing)', 'Distinguishes himself at Zhengcunba in the civil war', 'When the Jianwen Emperor moved against the princes, Zhu Di rebelled. In the winter of 1399 the imperial commander Li Jinghong besieged Beiping, and the prince returned to rout him at Zhengcunba, east of the city. Ma He served with distinction in this and later battles, and the place is said to be the source of his new surname.']),
      w(1404, 118.78, 32.06,
        ['南京', '以靖难之功获赐姓“郑”，任内官监太监', '朱棣攻入南京即位，是为明成祖（永乐帝）。1404年初，他亲笔书写“郑”字赐给马和为姓，并升任他为内官监太监。此时朝廷已下令在南京龙江等地大造海船，为出使西洋做准备。'],
        ['Nanjing', 'Granted the surname Zheng and made Grand Director', 'Zhu Di took Nanjing and the throne as the Yongle Emperor. Early in 1404 he bestowed the surname Zheng on Ma He, writing the character himself, and promoted him to Grand Director of the Directorate of Palace Servants. Orders had already gone out to build ocean-going ships at the Longjiang yards in Nanjing and elsewhere.'],
        { wiki: { zh: '龙江船厂', en: 'Longjiang Shipyard' } }),
      w(1405, 121.13, 31.6,
        ['刘家港（今江苏太仓浏河）', '首次下西洋，率船二百余艘', '1405年7月，郑和与副使王景弘奉命出使西洋，船队从刘家港出发，据记载有大小船只二百余艘、官兵水手等二万七千余人，先到福建长乐太平港等候冬季的东北季风。史书所载最大的宝船长四十四丈，其实际尺寸至今仍有争论。'],
        ['Liujiagang (now Liuhe, Taicang, Jiangsu)', 'Sails on the first voyage with over two hundred ships', 'In July 1405 Zheng He and his deputy Wang Jinghong were ordered to the Western Ocean. The fleet that left Liujiagang is recorded as more than two hundred vessels carrying some 27,000 men; it waited at Changle in Fujian for the winter monsoon. The size of the largest treasure ships, given in the histories as 44 zhang long, is still debated.'],
        { event: 'zheng-he-voyages' }),
      w(1405, 109.22, 13.77,
        ['占城（今越南归仁）', '首站抵达占城', '船队乘东北季风南下，顺风十昼夜到达占城的新州港（今越南归仁）。占城是历次下西洋的第一站，国王骑象出迎。后来随行的通事马欢在《瀛涯胜览》中记下了这里的犀角、象牙和伽蓝香。'],
        ['Champa (now Quy Nhon, Vietnam)', 'Makes first landfall in Champa', 'Riding the north-east monsoon, the fleet reached the Champa port of Xinzhou, now Quy Nhon, after about ten days at sea. Champa was the first stop on every voyage, and its king came out on an elephant to greet the envoys. Ma Huan, an interpreter on later voyages, recorded its rhinoceros horn, ivory and aloeswood.'],
        { sea: true, via: [[122.6, 30.0], [120.2, 24.6], [116.5, 21.7], [111.5, 16.5]] }),
      w(1406, 112.75, -7.25,
        ['爪哇（今印度尼西亚泗水一带）', '抵达爪哇', '船队来到满者伯夷王国治下的爪哇，适逢东、西二王交战，上岸贸易的一百七十名明朝官兵被西王的军队误杀。西王遣使谢罪，明成祖责令赔偿黄金六万两，后来只收一万两便免去了其余。'],
        ['Java (near Surabaya, Indonesia)', 'Reaches Java', 'The fleet arrived in Majapahit Java during a war between its eastern and western courts, and 170 of the Chinese who had gone ashore to trade were killed by the western king\'s troops. He sent envoys to apologise; the Yongle Emperor demanded 60,000 taels of gold in compensation but later waived all but 10,000.'],
        { sea: true, via: [[108.5, 8.0], [107.5, 0.0], [110.0, -5.6]] }),
      w(1407, 104.76, -2.99,
        ['旧港（今印度尼西亚巨港）', '剿灭盘踞旧港的海盗陈祖义', '首航返程途中，船队在旧港遭遇广东籍海盗首领陈祖义。陈祖义诈降，图谋袭击船队，郑和得到当地华人施进卿的密报，设伏击溃其众，歼敌五千余人，将陈祖义押回南京处死。明廷随后在此设旧港宣慰司。'],
        ['Old Port (now Palembang, Indonesia)', 'Destroys the pirate fleet of Chen Zuyi at Palembang', 'On the way home from the first voyage the fleet met Chen Zuyi, a Cantonese pirate chief who controlled Palembang. Chen feigned surrender while planning an attack, but Zheng He, warned by the local Chinese leader Shi Jinqing, ambushed him, killed some five thousand of his men and took him to Nanjing for execution.'],
        { sea: true, via: [[108.0, -5.6], [106.0, -3.6]] }),
      w(1407, 102.25, 2.2,
        ['满剌加（今马来西亚马六甲）', '在满剌加设立官厂，作为船队中转站', '满剌加刚刚立国，为摆脱暹罗的控制而寻求明朝保护。郑和奉命赐其国王银印冠带，并在当地建起有围栅和仓库的“官厂”，各分船队返航时在此会合、囤积货物，等候西南季风一同回国。'],
        ['Malacca (now Malacca, Malaysia)', 'Sets up a depot at Malacca', 'Newly founded Malacca sought Ming protection against Siam. Zheng He delivered a silver seal and robes to its ruler and built a stockaded depot with warehouses. The squadrons of each voyage reassembled there on the way home, stored their cargoes and waited for the south-west monsoon to return to China together.'],
        { sea: true, via: [[105.6, -1.6], [104.3, 1.2]], wiki: { zh: '马六甲苏丹国', en: 'Malacca Sultanate' } }),
      w(1409, 80.22, 6.03,
        ['锡兰山（今斯里兰卡加勒）', '立汉、泰米尔、波斯三种文字的布施碑', '第三次下西洋时，郑和在锡兰山的佛寺布施金银、丝绢和香油，并立碑纪念。石碑用汉文、泰米尔文和波斯文分别向佛陀、印度教神祇和真主致敬，1911年在加勒被发现。返程中他击败并俘获了袭击船队的锡兰国王亚烈苦奈儿。'],
        ['Ceylon (now Galle, Sri Lanka)', 'Erects a trilingual stele in Ceylon', 'On the third voyage Zheng He made offerings of gold, silver, silk and oil at a Buddhist shrine in Ceylon and set up a stele. Its Chinese, Tamil and Persian texts honour the Buddha, a Hindu deity and Allah respectively; it was found at Galle in 1911. On the way home he defeated and captured the hostile king Alakeshvara.'],
        { sea: true, via: [[100.2, 4.0], [95.0, 6.0], [86.0, 5.5]], wiki: { zh: '布施锡兰山佛寺碑', en: 'Galle Trilingual Inscription' } }),
      w(1409, 75.78, 11.25,
        ['古里（今印度科泽科德）', '多次停驻古里，立碑纪事', '古里是印度西南海岸的胡椒贸易中心，被称为“西洋大国”，也是前三次下西洋的终点。郑和首航到此时曾立碑纪念，碑文称“其国去中国十万余里，民物咸若，熙皞同风”。双方交易时以击掌为定，事后绝不反悔。'],
        ['Calicut (now Kozhikode, Kerala, India)', 'Calls repeatedly at Calicut and sets up a stele', 'Calicut, centre of the pepper trade on India\'s south-west coast and the "great country of the Western Ocean", was the destination of the first three voyages. On his first visit Zheng He erected a commemorative stele. Ma Huan describes how bargains there were sealed with a clasp of hands and never afterwards broken.'],
        { sea: true, via: [[77.4, 7.4], [75.6, 9.5]], wiki: { zh: '科泽科德', en: 'Kozhikode' } }),
      w(1414, 56.27, 27.1,
        ['忽鲁谟斯（今伊朗霍尔木兹岛）', '第四次下西洋抵达波斯湾口', '第四次下西洋首次越过印度，从古里横渡阿拉伯海，顺风二十五日到达波斯湾口的忽鲁谟斯。马欢称这里各国商船云集，“国民皆富”。船队在此换得宝石、珍珠、狮子和西马，分遣的支队还到了孟加拉。'],
        ['Hormuz (now Hormuz Island, Iran)', 'Reaches Hormuz on the fourth voyage', 'The fourth voyage was the first to go beyond India, crossing the Arabian Sea from Calicut to Hormuz in about twenty-five days. Ma Huan found the island crowded with merchant ships from every country and its people all rich. The fleet traded for gems, pearls, lions and horses, while a detached squadron visited Bengal.'],
        { sea: true, via: [[70.0, 15.5], [61.0, 22.5]], wiki: { zh: '霍尔木兹岛', en: 'Hormuz Island' } }),
      w(1417, 45.03, 12.78,
        ['阿丹（今也门亚丁）', '分船队访问阿拉伯半岛', '第五次下西洋护送各国使臣回国，船队到达阿拉伯半岛南端的阿丹。据马欢记述，当地国王率大小头目到海边迎接诏书。阿丹先后向明朝进贡麒麟（长颈鹿）、狮子等珍禽异兽，船队则在此买到大颗的猫睛石和珊瑚树。'],
        ['Aden (now Aden, Yemen)', 'A squadron visits the Arabian Peninsula', 'The fifth voyage, which carried foreign envoys home, reached Aden at the southern tip of Arabia. Ma Huan relates that its ruler came down to the shore with his officers to receive the imperial edict. Aden sent the Ming court giraffes, which were hailed as the auspicious qilin, as well as lions and other animals.'],
        { sea: true, via: [[58.5, 22.0], [54.0, 15.0], [48.0, 12.8]] }),
      w(1417, 45.34, 2.05,
        ['木骨都束（今索马里摩加迪沙）', '抵达东非', '船队沿非洲之角南下，访问木骨都束、卜剌哇（今布拉瓦）等地。费信的《星槎胜览》记载木骨都束“垒石为城”，石屋高四五层，当地干旱少雨，居民以捕鱼和畜牧为生。这些城邦此前已遣使随船队到过中国。'],
        ['Mogadishu (now Mogadishu, Somalia)', 'Reaches East Africa', 'The fleet rounded the Horn of Africa and visited Mogadishu and Brava. Fei Xin\'s account of the voyages describes Mogadishu as a town of stone walls and stone houses four or five storeys high, in a dry country whose people lived by fishing and herding. Envoys from these towns had already travelled to China with the fleet.'],
        { sea: true, via: [[51.6, 11.8], [49.5, 6.5]] }),
      w(1418, 40.12, -3.22,
        ['麻林（今肯尼亚马林迪）', '船队最远抵达东非麻林一带', '麻林是历次下西洋所到的最南端一带。1415年麻林曾遣使向明朝进献“麒麟”（长颈鹿），明成祖亲自到奉天门迎接。第五次下西洋把麻林等国的使臣送回本国，并带回斑马、狮子等动物。'],
        ['Malindi (now Malindi, Kenya)', 'The fleet\'s furthest reach, on the East African coast', 'Malindi lay near the southern limit of the voyages. In 1415 its envoys had presented a giraffe, taken for the auspicious qilin, which the Yongle Emperor received in person at the palace gate. The fifth voyage carried the ambassadors of Malindi and other states home and returned with zebras, lions and other animals.'],
        { sea: true, via: [[42.6, -1.0]] }),
      w(1431, 119.52, 25.96,
        ['长乐（今福建福州长乐区）', '第七次下西洋前立《天妃灵应之记》碑', '明成祖死后下西洋一度停止，郑和改任南京守备。1430年明宣宗命他再度出使。船队在长乐候风时，年已六十的郑和在南山天妃宫立碑，回顾此前六次航行的经过，这块《天妃灵应之记》碑至今保存在长乐。'],
        ['Changle (now Changle District, Fuzhou, Fujian)', 'Erects the Changle inscription before the seventh voyage', 'The voyages lapsed after the Yongle Emperor died, and Zheng He served as commandant of Nanjing until the Xuande Emperor ordered a new expedition in 1430. While the fleet waited at Changle for the monsoon, Zheng He, now about sixty, set up a stele at the temple of the sea goddess Tianfei recounting the earlier voyages. It survives in Changle.'],
        { sea: true, via: [[48.0, -2.0], [72.0, 5.0], [92.0, 5.5], [104.5, 1.4], [109.5, 11.0], [116.5, 21.5]] }),
      w(1433, 75.78, 11.25,
        ['古里（今印度科泽科德）', '第七次下西洋途中病逝于古里一带', '第七次下西洋的船队再次到达忽鲁谟斯，通事马欢等七人还随古里的船去了麦加。一般认为郑和在1433年返航途中病逝于古里附近，葬于海上；另一说他回国后卒于南京。南京牛首山有他的墓，或为衣冠冢。此后明朝再未组织大规模远航。'],
        ['Calicut (now Kozhikode, Kerala, India)', 'Dies near Calicut on the seventh voyage', 'The seventh fleet again reached Hormuz, and seven men including Ma Huan went on to Mecca. Zheng He is generally thought to have died near Calicut on the way home in 1433 and been buried at sea, though some hold that he died later in Nanjing, where a tomb stands on Niushou Hill. The Ming sent no more great fleets.'],
        { sea: true, via: [[117.5, 22.0], [110.0, 11.0], [104.5, 1.4], [96.0, 6.0], [82.0, 5.8], [76.6, 8.4]] }),
    ],
    wiki: { zh: '郑和', en: 'Zheng He' },
  },
];
